/* test_proto.c — native test suite for src/proto.c.
 *
 * Three layers:
 *   1. Replay of the fixtures generated by gen_streams.py, i.e. the literal
 *      byte streams produced by FlashGBX's FirmwareUpdater, the unlocker's
 *      gbflash_serial_update.py and the creator's getserial.py while they were
 *      driving this very state machine. The device's answers must come out
 *      byte-identical to what those hosts accepted, the reconstructed image
 *      must equal the source file, and nothing below 0x3E00 may be touched.
 *   2. Synthetic full-update runs, for image shapes the real files do not
 *      cover (unaligned tail, exactly-at-the-limit, one byte over).
 *   3. Adversarial framing and session cases.
 *   4. Single-fault injection into the flash model — every erase, every
 *      programmed word and every read of a whole session, in four flavours —
 *      asserting that the device never reports success it did not achieve and
 *      never leaves a valid boot-info record over an image that is not the one
 *      the host sent.
 *
 * The summary line reports two numbers. The count of check() CALL SITES is the
 * number of distinct claims; the execution count is much larger and dominated
 * by loops (most of all the replay loop's five assertions per response frame
 * and the fault sweep), so it should not be read as breadth.
 *
 * Built with -fsanitize=undefined,local-bounds, which traps any index outside
 * the fixed-size arrays inside bl_proto — the parser's entire overflow
 * surface. The bl_proto object itself sits flush against a PROT_NONE guard
 * page (see guard.h; AddressSanitizer hangs at startup on this machine, and
 * guard.h documents that in detail).
 */

#include <stdarg.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

#include "proto.h"
#include "dev_api.h"
#include "flash_stub.h"
#include "guard.h"

/* ------------------------------------------------------------------ */
/* Tiny test framework                                                 */
/* ------------------------------------------------------------------ */

static int g_pass, g_fail;
static const char *g_group = "";

/* Distinct check() call sites actually executed, so the summary can report
 * "N assertions, M executions" instead of only the execution count. The old
 * headline number was ~15x inflated by loops — 69% of it came from a single
 * five-assertions-per-frame replay loop — and a gate document should not read
 * a loop trip count as breadth of coverage. */
static int g_sites[512];
static int g_nsites;

static void note_site(int line)
{
    int i;
    for (i = 0; i < g_nsites; i++) if (g_sites[i] == line) return;
    if (g_nsites < (int)(sizeof g_sites / sizeof g_sites[0]))
        g_sites[g_nsites++] = line;
}

static void group(const char *name)
{
    g_group = name;
    printf("\n== %s\n", name);
}

static int check_at(int line, int cond, const char *fmt, ...)
    __attribute__((format(printf, 3, 4)));

static int check_at(int line, int cond, const char *fmt, ...)
{
    va_list ap;
    note_site(line);
    if (cond) {
        g_pass++;
    } else {
        g_fail++;
        printf("  FAIL [%s:%d] ", g_group, line);
        va_start(ap, fmt);
        vprintf(fmt, ap);
        va_end(ap);
        printf("\n");
    }
    return cond;
}

#define check(cond, ...) check_at(__LINE__, (cond), __VA_ARGS__)

/* A measured-but-tolerated behaviour: reported every run so a regression is
 * visible, but not a failure. Used only where the tolerance is argued in a
 * comment at the call site. */
static int g_warn;

static void warn(const char *fmt, ...) __attribute__((format(printf, 1, 2)));

static void warn(const char *fmt, ...)
{
    va_list ap;
    g_warn++;
    printf("  NOTE [%s] ", g_group);
    va_start(ap, fmt);
    vprintf(fmt, ap);
    va_end(ap);
    printf("\n");
}

/* ------------------------------------------------------------------ */
/* Wire helpers. Frames are built with bl_frame_build(), the same       */
/* function the device uses, so the pad rule is exercised rather than   */
/* reimplemented.                                                       */
/* ------------------------------------------------------------------ */

#define RXCAP 65536

static uint8_t *g_rx;          /* device -> host, from the last feed()  */
static uint32_t g_rxn;

/* When set, every feed() goes through bl_proto_feed_buf() instead of the
 * per-byte bl_proto_feed(). See t_feed_buf(). */
static int g_use_feed_buf;

static void feed(const uint8_t *b, uint32_t n)
{
    g_rxn = g_use_feed_buf ? dev_feed_buf(b, n, g_rx, RXCAP)
                           : dev_feed(b, n, g_rx, RXCAP);
    if (g_rxn == 0xFFFFFFFFu) { printf("  FATAL: response overflow\n"); exit(2); }
}

static uint16_t be16r(const uint8_t *p) { return (uint16_t)((p[0] << 8) | p[1]); }

typedef struct {
    int      valid;
    uint32_t intro, outro;
    uint8_t  sender;
    uint16_t seq, cmd, plen;
    const uint8_t *payload;
    uint32_t total;
} frame_t;

/* Parse one device frame exactly the way the unlocker's get_packet() does:
 * 11 header bytes, payload_len payload bytes, 4 outro bytes, and NEVER a pad
 * byte. If the device ever emits an even payload_len this parse desyncs — the
 * hazard described in docs/PROTOCOL.md — so parsing the whole stream this
 * way is itself the test for it. */
static frame_t parse_frame(const uint8_t *p, uint32_t n)
{
    frame_t f;
    memset(&f, 0, sizeof f);
    if (n < 15) return f;
    f.intro = ((uint32_t)p[0] << 24) | ((uint32_t)p[1] << 16)
            | ((uint32_t)p[2] << 8) | p[3];
    f.sender = p[4];
    f.seq  = be16r(p + 5);
    f.cmd  = be16r(p + 7);
    f.plen = be16r(p + 9);
    if ((uint32_t)f.plen + 15u > n) return f;
    f.payload = p + 11;
    f.outro = ((uint32_t)p[11 + f.plen] << 24) | ((uint32_t)p[12 + f.plen] << 16)
            | ((uint32_t)p[13 + f.plen] << 8) | p[14 + f.plen];
    f.total = 15u + f.plen;
    f.valid = 1;
    return f;
}

static int frame_ok(const frame_t *f, uint16_t seq, uint16_t cmd)
{
    return f->valid && f->intro == 0x48484A4Au && f->outro == 0x4A4A4848u
        && f->seq == seq && f->cmd == cmd;
}

/* Build a host frame into a fresh heap buffer. Caller frees. */
static uint8_t *mkframe(uint16_t seq, uint16_t cmd, const uint8_t *pl,
                        uint16_t plen, uint32_t *out_len)
{
    uint8_t *buf = malloc(16u + plen + 8u);
    uint16_t n = bl_frame_build(buf, 0x00, seq, cmd, pl, plen);
    *out_len = n;
    return buf;
}

static void send_frame(uint16_t seq, uint16_t cmd, const uint8_t *pl,
                       uint16_t plen)
{
    uint32_t n;
    uint8_t *f = mkframe(seq, cmd, pl, plen, &n);
    feed(f, n);
    free(f);
}

static uint16_t crc16(const uint8_t *p, uint32_t n) { return bl_crc16(p, n); }

/* 0x24 payload: index || clen || chunk || crc. crc_override != -1 forces a
 * wrong CRC; len_field != -1 forces a lying chunk_len. */
static uint8_t *mk_data_payload(uint16_t index, const uint8_t *chunk,
                                uint16_t clen, long crc_override,
                                long len_field, uint16_t *out_plen)
{
    uint16_t lf = (len_field < 0) ? clen : (uint16_t)len_field;
    uint16_t c  = (crc_override < 0) ? crc16(chunk, clen)
                                     : (uint16_t)crc_override;
    uint8_t *pl = malloc((size_t)clen + 6u);
    pl[0] = (uint8_t)(index >> 8); pl[1] = (uint8_t)index;
    pl[2] = (uint8_t)(lf >> 8);    pl[3] = (uint8_t)lf;
    memcpy(pl + 4, chunk, clen);
    pl[4 + clen] = (uint8_t)(c >> 8);
    pl[5 + clen] = (uint8_t)c;
    *out_plen = (uint16_t)(clen + 6u);
    return pl;
}

/* ------------------------------------------------------------------ */
/* Synthetic image builder                                             */
/* ------------------------------------------------------------------ */

/* Lay out a valid GBFlash update image: a 512-byte boot-info page followed by
 * applen application bytes. Exactly the layout of the real fw.bin. */
static uint8_t *build_image(uint32_t applen, uint32_t seed, uint32_t *out_len)
{
    uint32_t total = 0x200u + applen;
    uint8_t *img = malloc(total);
    uint32_t s = seed | 1u;
    uint32_t i;
    uint16_t appcrc, hcrc;

    memset(img, 0xFF, total);
    for (i = 0; i < applen; i++) {
        s = s * 1103515245u + 12345u;
        img[0x200 + i] = (uint8_t)(s >> 16);
    }
    /* The application's initial SP must look like an SRAM pointer; the boot
     * decision, proto.c's app_gates() and its flash_verify() all test it. */
    if (applen >= 4) {
        img[0x200] = 0x00; img[0x201] = 0x80; img[0x202] = 0x00; img[0x203] = 0x20;
    }
    /* And its reset vector must be a Thumb pointer landing inside the image —
     * bl_app_valid() step 4b, and now app_gates() at finalize too. Random
     * bytes here pass neither, so every synthetic image needs a real one.
     * 0x4000 + 8 keeps it inside even the shortest accepted application
     * (BL_APP_MIN_LEN is 0x90), and the odd byte sets the Thumb bit. */
    if (applen >= 8) {
        uint32_t rv = 0x4000u + 8u + 1u;
        img[0x204] = (uint8_t)rv;         img[0x205] = (uint8_t)(rv >> 8);
        img[0x206] = (uint8_t)(rv >> 16); img[0x207] = (uint8_t)(rv >> 24);
    }

    img[0] = 0xFF; img[1] = 0xFF;                       /* marker, untouched */
    img[2] = 'L'; img[3] = 'F'; img[4] = 'B'; img[5] = 'G';
    appcrc = crc16(img + 0x200, applen);
    img[6] = (uint8_t)appcrc; img[7] = (uint8_t)(appcrc >> 8);
    img[8]  = (uint8_t)applen;         img[9]  = (uint8_t)(applen >> 8);
    img[10] = (uint8_t)(applen >> 16); img[11] = (uint8_t)(applen >> 24);
    hcrc = crc16(img, 12);
    img[12] = (uint8_t)hcrc; img[13] = (uint8_t)(hcrc >> 8);

    *out_len = total;
    return img;
}

/* Drive a complete update the way every real host does. Returns:
 *   0  success (all data acked, finalize acked)
 *  -1  a data packet was NAKed
 *  -2  finalize was NAKed
 *  -3  a malformed or missing response
 * `stop_at` > 0 truncates the run after that many data packets (no finalize).
 */
static int run_update(const uint8_t *img, uint32_t len, uint32_t page,
                      uint32_t stop_at)
{
    uint32_t npkt = (len + page - 1u) / page;
    uint16_t seq = 1;
    uint32_t k;
    frame_t f;

    send_frame(seq, BL_CMD_INIT, 0, 0);
    f = parse_frame(g_rx, g_rxn);
    if (!frame_ok(&f, seq, BL_CMD_INIT)) return -3;
    if (f.plen != 9 || be16r(f.payload + 1) != 0x0003u) return -3;
    seq = 2;

    for (k = 1; k <= npkt; k++) {
        uint32_t off = (k - 1u) * page;
        uint16_t clen = (uint16_t)((len - off > page) ? page : (len - off));
        uint16_t plen;
        uint8_t *pl = mk_data_payload((uint16_t)k, img + off, clen, -1, -1,
                                      &plen);
        send_frame(seq, BL_CMD_DATA, pl, plen);
        free(pl);
        f = parse_frame(g_rx, g_rxn);
        if (!frame_ok(&f, seq, BL_CMD_DATA) || f.plen != 3) return -3;
        if (be16r(f.payload) != (uint16_t)k) return -3;
        if (f.payload[2] != 0x01) return -1;
        seq++;
        if (stop_at && k >= stop_at) return 0;
    }

    {
        uint16_t c = crc16(img, len);
        uint8_t pl[4];
        pl[0] = (uint8_t)(c >> 8); pl[1] = (uint8_t)c;
        pl[2] = (uint8_t)(~c >> 8); pl[3] = (uint8_t)(~c);
        send_frame(seq, BL_CMD_FINALIZE, pl, 4);
        f = parse_frame(g_rx, g_rxn);
        if (!frame_ok(&f, seq, BL_CMD_FINALIZE) || f.plen != 1) return -3;
        if (f.payload[0] != 0x01) return -2;
    }
    return 0;
}

/* Read the boot-info commit word. While bytes 12..13 at 0x3E00 are still
 * erased there is no valid record, so the boot decision refuses the
 * application and the device comes back up in update mode. That is the
 * fail-safe, and the single most important thing to hold under every failure
 * the tests below inject. */
static int commit_word_blank(void)
{
    uint8_t h[16];
    dev_flash_read(0x3E00u, h, 16);
    return h[12] == 0xFF && h[13] == 0xFF;
}

static int flash_equals(uint32_t addr, const uint8_t *want, uint32_t n)
{
    uint8_t *got = malloc(n);
    int r;
    dev_flash_read(addr, got, n);
    r = memcmp(got, want, n) == 0;
    free(got);
    return r;
}

/* ------------------------------------------------------------------ */
/* Layer 1 — fixture replay                                            */
/* ------------------------------------------------------------------ */

static uint8_t *slurp(const char *path, uint32_t *len)
{
    FILE *fp = fopen(path, "rb");
    uint8_t *buf;
    long n;
    if (!fp) return 0;
    fseek(fp, 0, SEEK_END);
    n = ftell(fp);
    fseek(fp, 0, SEEK_SET);
    buf = malloc((size_t)n ? (size_t)n : 1u);
    if (fread(buf, 1, (size_t)n, fp) != (size_t)n) { fclose(fp); free(buf); return 0; }
    fclose(fp);
    *len = (uint32_t)n;
    return buf;
}

static const char *g_fixdir = "fixtures";

static char *fixpath(const char *name, const char *suffix)
{
    static char buf[1024];
    snprintf(buf, sizeof buf, "%s/%s%s", g_fixdir, name, suffix);
    return buf;
}

/* Replay one recorded conversation. `image` (may be NULL) is the file the host
 * was flashing; when given, the modelled flash must end up identical to it. */
static void replay(const char *name, const char *image_path)
{
    uint32_t h2dn = 0, d2hn = 0, imgn = 0, i;
    uint8_t *h2d = slurp(fixpath(name, ".h2d.bin"), &h2dn);
    uint8_t *d2h = slurp(fixpath(name, ".d2h.bin"), &d2hn);
    uint8_t *img = image_path ? slurp(image_path, &imgn) : 0;
    uint32_t frames = 0, pos;

    if (!check(h2d != 0 && d2h != 0,
               "%s: fixture missing — run `make fixtures`", name)) {
        free(h2d); free(d2h); free(img);
        return;
    }
    check(img != 0 || image_path == 0, "%s: image %s not readable",
          name, image_path ? image_path : "");

    /* --- (a) whole stream in one go --- */
    dev_reset();
    feed(h2d, h2dn);
    check(g_rxn == d2hn,
          "%s: produced %u response bytes, the host received %u",
          name, g_rxn, d2hn);
    if (g_rxn == d2hn)
        check(memcmp(g_rx, d2h, d2hn) == 0,
              "%s: response bytes differ from what the real host accepted",
              name);
    check(dev_finalized(), "%s: not finalized after replay", name);
    check(dev_bootloader_intact(),
          "%s: bootloader region below 0x3E00 was modified", name);
    check(dev_flash_stat(FS_STAT_FLOOR_HITS) == 0,
          "%s: %u write attempts below 0x3E00", name,
          dev_flash_stat(FS_STAT_FLOOR_HITS));
    check(dev_flash_stat(FS_STAT_VIOLATIONS) == 0,
          "%s: %u flash-driver contract violations", name,
          dev_flash_stat(FS_STAT_VIOLATIONS));
    check(dev_flash_stat(FS_STAT_VERIFY_FAILS) == 0,
          "%s: %u programs over non-erased flash", name,
          dev_flash_stat(FS_STAT_VERIFY_FAILS));
    if (img) {
        check(flash_equals(0x3E00u, img, imgn),
              "%s: reconstructed image differs from %s", name, image_path);
        /* everything after the image, up to the end of its last sector and
         * one sector beyond, must still be erased */
        {
            uint32_t after = 0x3E00u + imgn;
            uint8_t *tail = malloc(0x400);
            uint32_t j, bad = 0;
            dev_flash_read(after, tail, 0x400);
            for (j = 0; j < 0x400; j++) if (tail[j] != 0xFF) bad++;
            check(bad == 0, "%s: %u non-erased bytes past the image", name, bad);
            free(tail);
        }
    }

    /* --- (b) every response frame must be well formed and unpadded --- */
    pos = 0;
    {
        /* The finalize exchange, explicitly: the host must have sent the
         * whole-file CRC16 and the device must have answered 0x01. */
        uint32_t last = 0, q = 0;
        frame_t lf;
        while (q < d2hn) {
            frame_t ff = parse_frame(d2h + q, d2hn - q);
            if (!ff.valid) break;
            last = q;
            q += ff.total;
        }
        lf = parse_frame(d2h + last, d2hn - last);
        check(lf.valid && lf.cmd == 0x23u && lf.plen == 1
              && lf.payload[0] == 0x01,
              "%s: the last response is not a successful 0x23 ack", name);
        if (img) {
            uint16_t want = crc16(img, imgn);
            /* find the 0x23 request in the host stream */
            uint32_t r, found = 0;
            for (r = 0; r + 20u <= h2dn; r++) {
                if (h2d[r] == 0x48 && h2d[r+1] == 0x48 && h2d[r+2] == 0x4A
                    && h2d[r+3] == 0x4A && h2d[r+7] == 0x00 && h2d[r+8] == 0x23
                    && h2d[r+9] == 0x00 && h2d[r+10] == 0x04) {
                    uint16_t sent = be16r(h2d + r + 11);
                    uint16_t inv  = be16r(h2d + r + 13);
                    check(sent == want,
                          "%s: host finalized with CRC 0x%04X, image CRC is "
                          "0x%04X", name, sent, want);
                    check((uint16_t)(sent ^ inv) == 0xFFFFu,
                          "%s: finalize inverse field is not the inverse", name);
                    found = 1;
                    break;
                }
            }
            check(found, "%s: no 0x23 finalize frame in the host stream", name);
        }
    }
    while (pos < d2hn) {
        frame_t f = parse_frame(d2h + pos, d2hn - pos);
        if (!check(f.valid, "%s: response stream truncated at %u", name, pos))
            break;
        check(f.intro == 0x48484A4Au, "%s: frame %u bad intro", name, frames);
        check(f.outro == 0x4A4A4848u, "%s: frame %u bad outro", name, frames);
        check((f.plen & 1u) == 1u,
              "%s: frame %u payload_len %u is EVEN — the host will desync by "
              "one byte on the next frame", name, frames, f.plen);
        check(f.cmd == 0x21u || f.cmd == 0x23u || f.cmd == 0x24u,
              "%s: frame %u unexpected command 0x%02X", name, frames, f.cmd);
        pos += f.total;
        frames++;
    }
    check(pos == d2hn, "%s: %u trailing bytes after the last frame",
          name, d2hn - pos);

    /* --- (c) one byte at a time --- */
    dev_reset();
    {
        uint8_t *acc = malloc(RXCAP);
        uint32_t accn = 0;
        for (i = 0; i < h2dn; i++) {
            feed(h2d + i, 1);
            memcpy(acc + accn, g_rx, g_rxn);
            accn += g_rxn;
        }
        check(accn == d2hn && memcmp(acc, d2h, d2hn) == 0,
              "%s: byte-at-a-time feed differs from the bulk feed", name);
        check(dev_finalized(), "%s: byte-at-a-time run did not finalize", name);
        if (img) check(flash_equals(0x3E00u, img, imgn),
                       "%s: byte-at-a-time image mismatch", name);
        free(acc);
    }

    /* --- (d) random-sized bursts, several different chunkings --- */
    {
        uint32_t trial;
        uint32_t rng = 0xC0FFEEu;
        for (trial = 0; trial < 8; trial++) {
            uint8_t *acc = malloc(RXCAP);
            uint32_t accn = 0, p = 0;
            dev_reset();
            while (p < h2dn) {
                uint32_t take;
                rng = rng * 1664525u + 1013904223u;
                take = 1u + (rng >> 20) % 1500u;
                if (take > h2dn - p) take = h2dn - p;
                feed(h2d + p, take);
                memcpy(acc + accn, g_rx, g_rxn);
                accn += g_rxn;
                p += take;
            }
            check(accn == d2hn && memcmp(acc, d2h, d2hn) == 0,
                  "%s: burst feed (trial %u) differs from the bulk feed",
                  name, trial);
            check(dev_finalized(), "%s: burst trial %u did not finalize",
                  name, trial);
            free(acc);
        }
    }

    printf("  %s: %u host bytes, %u device bytes, %u frames — replayed\n",
           name, h2dn, d2hn, frames);

    free(h2d); free(d2h); free(img);
}

/* ------------------------------------------------------------------ */
/* Layer 3 — adversarial                                               */
/* ------------------------------------------------------------------ */

static void t_stray_trigger_bytes(void)
{
    static const uint8_t junk[] = {
        0xF1, 0x01,                       /* FlashGBX's trigger, twice over  */
        0xF1, 0x01,
        0x48, 0x48, 0x4A,                 /* a false start on the intro      */
        0x00, 0xFF, 0x48, 0x48, 0x4A, 0x4A/*!*/, /* overlapping candidate    */
    };
    frame_t f;
    uint32_t n;
    uint8_t *init;

    dev_reset();
    /* The trailing 48 48 4A 4A in `junk` IS a real intro, so the init frame
     * that follows would be mis-framed if the hunt were naive. Feed junk that
     * deliberately ends mid-frame, then resync. */
    feed(junk, sizeof junk);
    check(g_rxn == 0, "stray bytes produced %u response bytes", g_rxn);

    /* That dangling intro leaves the parser in the header state; a fresh init
     * frame must still be found once the bogus frame fails its outro.
     *
     * The exact count is pinned rather than left as ">= 24": the first init
     * frame is consumed as the bogus frame's header and payload, fails its
     * outro, and is then RECOVERED by the rescan — so both init frames are
     * answered, 48 bytes. Before the rescan landed this was 24. A change
     * either way is a change in resynchronisation behaviour and should have
     * to be acknowledged here. */
    init = mkframe(1, BL_CMD_INIT, 0, 0, &n);
    feed(init, n);
    check(g_rxn == 24, "the first init after a dangling intro returned %u "
          "bytes, expected 24 (recovered by the rescan)", g_rxn);
    feed(init, n);
    free(init);
    f = parse_frame(g_rx, g_rxn);
    check(g_rxn == 24 && f.valid && f.cmd == BL_CMD_INIT,
          "no init response after stray trigger bytes (%u bytes back)", g_rxn);

    /* And the pure case: F1 / 01 then a clean init. */
    dev_reset();
    {
        static const uint8_t trig[2] = { 0xF1, 0x01 };
        feed(trig, 2);
        check(g_rxn == 0, "F1/01 alone produced output");
        init = mkframe(1, BL_CMD_INIT, 0, 0, &n);
        feed(init, n);
        f = parse_frame(g_rx, g_rxn);
        check(g_rxn == 24 && frame_ok(&f, 1, BL_CMD_INIT) && f.plen == 9,
              "init after F1/01 did not answer correctly (%u bytes)", g_rxn);
        free(init);
    }
}

static void t_init_once_and_twice(void)
{
    uint32_t n, i;
    uint8_t *init = mkframe(1, BL_CMD_INIT, 0, 0, &n);
    uint8_t first[64];
    uint32_t firstn;

    dev_reset();
    feed(init, n);
    firstn = g_rxn;
    memcpy(first, g_rx, g_rxn);
    check(firstn == 24, "single init answered with %u bytes, expected 24", firstn);

    /* Statelessness: five more inits must give five identical answers. */
    for (i = 0; i < 5; i++) {
        feed(init, n);
        check(g_rxn == firstn && memcmp(g_rx, first, firstn) == 0,
              "init #%u answered differently from the first", i + 2);
    }
    {
        frame_t f = parse_frame(first, firstn);
        check(frame_ok(&f, 1, BL_CMD_INIT), "init response header wrong");
        check(f.plen == 9, "init payload_len %u, expected 9", f.plen);
        check(f.payload[0] == 0x00, "init payload[0] should be 0");
        check(be16r(f.payload + 1) == 0x0003u,
              "init payload[1:3] = 0x%04X, both hosts hard-gate on 0x0003",
              be16r(f.payload + 1));
        check(be16r(f.payload + 3) == 0x3E00u, "program_size wrong");
        check(f.payload[5] == 0 && f.payload[6] == 0, "payload[5:7] should be 0");
        check(be16r(f.payload + 7) == 0x0200u, "page_size wrong");
        check(f.sender == 0x00, "sender byte %u (unchecked by hosts, but "
              "0x00 is what the spec recommends)", f.sender);
    }
    free(init);
}

static uint32_t g_resync_cost[64];

/* REGRESSION — the resync hazard the harness audit measured.
 *
 * A dangling header that declares the largest payload the framer accepts (520)
 * used to eat 524 more bytes before it could fail its outro, i.e. ~33
 * back-to-back 16-byte init frames. Both hosts send exactly two init frames at
 * connect and then give up: FlashGBX's TryConnect() returns False and prints
 * "No device found."; the unlocker's connect_bootloader() does the same. So a
 * truncated write before connect looked like a dead device.
 *
 * Two changes closed it, both in the framer:
 *   - hdr_plausible() rejects a header no real host could have sent. This one
 *     is cmd 0x21 with payload_len 520, which is refused after 11 bytes rather
 *     than after 535;
 *   - a framing failure rescans the bytes the bad frame consumed for a later
 *     intro instead of discarding them.
 * The cost is now ZERO swallowed frames: the very next init frame is answered.
 */
static void t_resync_worst_case(void)
{
    uint8_t hdr[11];
    uint32_t n, tries;
    uint8_t *init = mkframe(1, BL_CMD_INIT, 0, 0, &n);

    dev_reset();
    hdr[0] = 0x48; hdr[1] = 0x48; hdr[2] = 0x4A; hdr[3] = 0x4A;
    hdr[4] = 0x00; hdr[5] = 0x00; hdr[6] = 0x01;
    hdr[7] = 0x00; hdr[8] = 0x21;
    hdr[9] = 0x02; hdr[10] = 0x08;              /* payload_len = 520 */
    feed(hdr, 11);
    check(g_rxn == 0, "a bare max-length header should not answer");
    check(dev_proto_stat(DEV_PS_STATE) == 0,
          "an impossible header (0x21 with payload_len 520) must be refused at "
          "the header, not after swallowing 524 more bytes");

    for (tries = 1; tries <= 64; tries++) {
        feed(init, n);
        if (g_rxn) break;
    }
    check(tries == 1, "recovery from a dangling 520-byte header took %u init "
          "frames; the hosts provide 2 and the framer must need 1", tries);
    printf("  worst-case resync: a dangling max-length header swallows %u "
           "init frames (%u bytes) before the next one is answered\n",
           tries - 1u, (tries - 1u) * n);
    /* The recovery itself must be clean. */
    {
        frame_t f = parse_frame(g_rx, g_rxn);
        check(g_rxn == 24, "recovery produced %u response bytes, expected 24",
              g_rxn);
        check(frame_ok(&f, 1, BL_CMD_INIT), "recovery frame malformed");
        check(dev_proto_stat(DEV_PS_STATE) == 0,
              "parser did not return to the intro hunt");
    }
    free(init);
}

/* REGRESSION — headers no real host can send are refused at the header.
 *
 * Each of these is 11 bytes: intro, sender, seq, cmd, payload_len. All three
 * host implementations emit 0x21 with payload_len 0, 0x23 with 4, and 0x24
 * with chunk_len + 6. Anything else is a desynchronised parse, and continuing
 * to read `payload_len` bytes on the strength of it is what swallows the
 * frames behind it. The framer must be back in the intro hunt immediately, and
 * the next init frame must be answered.
 *
 * Unknown commands are deliberately exempt: their documented behaviour is
 * "consume whole, stay silent", and a future command's payload shape is not
 * ours to guess. t_odd_and_even_payloads covers that.
 */
static void t_implausible_headers(void)
{
    static const struct { uint16_t cmd, plen; const char *what; } cases[] = {
        { 0x0021u, 1u,   "0x21 with payload_len 1"   },
        { 0x0021u, 4u,   "0x21 with payload_len 4"   },
        { 0x0021u, 72u,  "0x21 with payload_len 72 (the 10-byte-truncation "
                         "shape)"                    },
        { 0x0021u, 520u, "0x21 with payload_len 520" },
        { 0x0023u, 0u,   "0x23 with payload_len 0"   },
        { 0x0023u, 3u,   "0x23 with payload_len 3"   },
        { 0x0023u, 5u,   "0x23 with payload_len 5"   },
        { 0x0024u, 0u,   "0x24 with payload_len 0"   },
        { 0x0024u, 5u,   "0x24 with payload_len 5"   }
    };
    uint32_t i, n;
    uint8_t *init = mkframe(1, BL_CMD_INIT, 0, 0, &n);

    for (i = 0; i < sizeof cases / sizeof cases[0]; i++) {
        uint8_t hdr[11];
        frame_t f;
        dev_reset();
        hdr[0] = 0x48; hdr[1] = 0x48; hdr[2] = 0x4A; hdr[3] = 0x4A;
        hdr[4] = 0x00; hdr[5] = 0x00; hdr[6] = 0x01;
        hdr[7] = (uint8_t)(cases[i].cmd >> 8); hdr[8] = (uint8_t)cases[i].cmd;
        hdr[9] = (uint8_t)(cases[i].plen >> 8); hdr[10] = (uint8_t)cases[i].plen;
        feed(hdr, 11);
        check(g_rxn == 0, "%s produced %u response bytes", cases[i].what, g_rxn);
        check(dev_proto_stat(DEV_PS_STATE) == 0,
              "%s left the parser mid-frame (state %u); it must be refused at "
              "the header", cases[i].what, dev_proto_stat(DEV_PS_STATE));
        feed(init, n);
        f = parse_frame(g_rx, g_rxn);
        check(g_rxn == 24 && frame_ok(&f, 1, BL_CMD_INIT),
              "%s swallowed the init frame behind it (%u bytes back)",
              cases[i].what, g_rxn);
    }

    /* And the legal shapes must still be accepted, in the same 11-byte form,
     * so the plausibility gate cannot silently become a denial of service. */
    {
        uint8_t hdr[11];
        frame_t f;
        dev_reset();
        hdr[0] = 0x48; hdr[1] = 0x48; hdr[2] = 0x4A; hdr[3] = 0x4A;
        hdr[4] = 0x00; hdr[5] = 0x00; hdr[6] = 0x01;
        hdr[7] = 0x00; hdr[8] = 0x21; hdr[9] = 0x00; hdr[10] = 0x00;
        feed(hdr, 11);
        check(dev_proto_stat(DEV_PS_STATE) == 3,
              "a legal 0x21 header must leave the parser waiting for the outro "
              "(state %u)", dev_proto_stat(DEV_PS_STATE));
        {
            static const uint8_t outro[4] = { 0x4A, 0x4A, 0x48, 0x48 };
            feed(outro, 4);
        }
        f = parse_frame(g_rx, g_rxn);
        check(g_rxn == 24 && frame_ok(&f, 1, BL_CMD_INIT),
              "a legal 0x21 header assembled byte-wise was not answered");
    }
    free(init);
}

/* A host process killed mid-firmware-write, and why bl_proto_idle() exists.
 *
 * This is the realistic trigger the audit identified: the host dies partway
 * through a 0x24 data frame, so the device is left in the payload state with a
 * LEGAL header and up to 522 bytes still outstanding. (A cable pull instead
 * power-cycles the device and self-heals.) The user then reruns the updater,
 * which sends two 16-byte init frames and gives up.
 *
 * The rescan in the framer cannot reach this one, and the sweep below is what
 * establishes that rather than assuming it: while fewer bytes are outstanding
 * than the host subsequently sends, the frame eventually fails its outro and
 * the rescan recovers the init behind it; once more are outstanding than the
 * 32 bytes two init frames carry, nothing fails, nothing is answered, and the
 * device looks dead. A frame that is still waiting has not gone wrong — only
 * the passage of time says otherwise.
 *
 * So the same sweep is run twice: without an idle notification, recording
 * where recovery stops working, and with one, where it must always work in a
 * single frame. That is the contract proto.h puts on the stage-3 receive loop.
 */
static void t_truncated_data_frame(void)
{
    uint32_t n, outstanding;
    uint8_t *init = mkframe(1, BL_CMD_INIT, 0, 0, &n);
    uint8_t chunk[512];
    uint32_t i;
    uint32_t bare_ok = 0, bare_dead = 0, first_dead = 0;
    uint32_t answered_truncated = 0;
    uint32_t idle_bad = 0, idle_frames_worst = 0, flash_touched = 0;

    for (i = 0; i < sizeof chunk; i++) chunk[i] = (uint8_t)(i * 7u + 3u);

    /* A 512-byte data frame is 534 bytes: 11 header + 518 payload + 4 outro +
     * 1 pad (the payload_len is even, so the frame is odd). Dropping just the
     * pad leaves a COMPLETE frame, which must still be acked — the module
     * deliberately never consumes a pad byte explicitly, because a host that
     * omitted one would otherwise cost it the first byte of the next intro.
     * Check that separately, then sweep genuine truncation from 2 bytes up. */
    {
        uint16_t plen;
        uint8_t *pl = mk_data_payload(1, chunk, 512, -1, -1, &plen);
        uint32_t fn;
        uint8_t *fr = mkframe(2, BL_CMD_DATA, pl, plen, &fn);
        frame_t f;
        check(fn == 534u, "a 512-byte data frame is %u bytes, expected 534", fn);
        dev_reset();
        send_frame(1, BL_CMD_INIT, 0, 0);
        feed(fr, fn - 1u);                    /* everything but the pad */
        f = parse_frame(g_rx, g_rxn);
        check(g_rxn == 18 && f.valid && f.payload[2] == 0x01,
              "a data frame with its pad byte omitted was not acked (%u bytes)",
              g_rxn);
        free(fr); free(pl);
    }

    for (outstanding = 2; outstanding <= 120; outstanding++) {
        uint16_t plen;
        uint8_t *pl = mk_data_payload(1, chunk, 512, -1, -1, &plen);
        uint32_t fn;
        uint8_t *fr = mkframe(2, BL_CMD_DATA, pl, plen, &fn);
        uint32_t cut = fn - outstanding;
        uint32_t tries;
        frame_t f;

        /* --- (a) no idle notification: measure, do not require --- */
        dev_reset();
        send_frame(1, BL_CMD_INIT, 0, 0);
        feed(fr, cut);                       /* host dies here */
        if (g_rxn != 0) answered_truncated++;
        for (tries = 1; tries <= 2; tries++) {
            feed(init, n);
            if (g_rxn) break;
        }
        f = parse_frame(g_rx, g_rxn);
        if (tries <= 2 && f.valid && f.cmd == BL_CMD_INIT) {
            bare_ok++;
        } else {
            if (!bare_dead) first_dead = outstanding;
            bare_dead++;
        }

        /* --- (b) with the idle notification the loop is required to send --- */
        dev_reset();
        send_frame(1, BL_CMD_INIT, 0, 0);
        feed(fr, cut);
        {
            uint32_t got = dev_idle(g_rx, RXCAP);
            if (got == 0xFFFFFFFFu) { printf("  FATAL: idle overflow\n"); exit(2); }
        }
        for (tries = 1; tries <= 2; tries++) {
            feed(init, n);
            if (g_rxn) break;
        }
        f = parse_frame(g_rx, g_rxn);
        if (!(tries == 1 && g_rxn == 24 && f.valid && f.cmd == BL_CMD_INIT))
            idle_bad++;
        if (tries > idle_frames_worst) idle_frames_worst = tries;
        if (dev_flash_stat(FS_STAT_VERIFY_FAILS) != 0 || !dev_bootloader_intact()
            || dev_flash_stat(FS_STAT_FLOOR_HITS) != 0)
            flash_touched++;

        free(fr); free(pl);
    }

    check(answered_truncated == 0,
          "%u truncated data frames were answered; an incomplete frame must "
          "produce nothing at all", answered_truncated);
    check(idle_bad == 0,
          "%u of 119 truncation points were not recovered in a single init "
          "frame after bl_proto_idle(); the stage-3 contract requires 1",
          idle_bad);
    check(idle_frames_worst == 1,
          "with bl_proto_idle() the worst truncation point still cost %u init "
          "frames", idle_frames_worst);
    check(flash_touched == 0,
          "%u truncation points touched flash during recovery", flash_touched);
    printf("  mid-payload truncation: without an idle notification the framer "
           "alone recovers %u of 119 cases (first failure at %u bytes "
           "outstanding); with bl_proto_idle() all 119 recover in 1 init "
           "frame\n", bare_ok, first_dead);
    free(init);
}

/* bl_proto_idle() must be harmless in every other state, and must never be
 * able to invent flash activity or a session. */
static void t_idle_is_safe(void)
{
    uint32_t imgn;
    uint8_t *img = build_image(0x600, 0xD1DL, &imgn);
    uint32_t n, i;
    uint8_t *init = mkframe(1, BL_CMD_INIT, 0, 0, &n);
    uint16_t plen;
    uint8_t *pl;
    frame_t f;

    /* Idle on a fresh device: silence, no state change. */
    dev_reset();
    check(dev_idle(g_rx, RXCAP) == 0, "idle on a fresh device answered");
    check(dev_proto_stat(DEV_PS_STATE) == 0, "idle disturbed the hunt state");
    feed(init, n);
    f = parse_frame(g_rx, g_rxn);
    check(g_rxn == 24 && frame_ok(&f, 1, BL_CMD_INIT),
          "init after an idle on a fresh device failed");

    /* Idle between every pair of frames of a real update must be invisible. */
    dev_reset();
    send_frame(1, BL_CMD_INIT, 0, 0);
    check(dev_idle(g_rx, RXCAP) == 0, "idle after a complete frame answered");
    {
        uint32_t npkt = (imgn + 511u) / 512u, k;
        uint16_t seq = 2;
        for (k = 1; k <= npkt; k++) {
            uint32_t off = (k - 1u) * 512u;
            uint16_t clen = (uint16_t)((imgn - off > 512u) ? 512u : (imgn - off));
            pl = mk_data_payload((uint16_t)k, img + off, clen, -1, -1, &plen);
            send_frame(seq, BL_CMD_DATA, pl, plen);
            free(pl);
            f = parse_frame(g_rx, g_rxn);
            check(f.valid && f.payload[2] == 0x01,
                  "packet %u failed with idles interleaved", k);
            check(dev_idle(g_rx, RXCAP) == 0,
                  "idle after data packet %u answered", k);
            seq++;
        }
        {
            uint16_t c = crc16(img, imgn);
            uint8_t p4[4];
            p4[0] = (uint8_t)(c >> 8); p4[1] = (uint8_t)c;
            p4[2] = (uint8_t)(~c >> 8); p4[3] = (uint8_t)(~c);
            send_frame(seq, BL_CMD_FINALIZE, p4, 4);
            f = parse_frame(g_rx, g_rxn);
            check(f.valid && f.payload[0] == 0x01,
                  "finalize failed with idles interleaved");
        }
        check(flash_equals(0x3E00u, img, imgn),
              "interleaved idles changed the stored image");
    }

    /* An idle in the middle of a frame drops that frame, and the host's retry
     * of the same frame must then be taken normally. */
    dev_reset();
    send_frame(1, BL_CMD_INIT, 0, 0);
    pl = mk_data_payload(1, img, 512, -1, -1, &plen);
    {
        uint32_t fn;
        uint8_t *fr = mkframe(2, BL_CMD_DATA, pl, plen, &fn);
        for (i = 1; i < fn; i += 37u) {
            uint32_t erases;
            dev_reset();
            send_frame(1, BL_CMD_INIT, 0, 0);
            erases = dev_flash_stat(FS_STAT_ERASES);
            feed(fr, i);
            (void)dev_idle(g_rx, RXCAP);
            check(dev_proto_stat(DEV_PS_STATE) == 0,
                  "idle left the parser mid-frame after %u bytes", i);
            check(dev_flash_stat(FS_STAT_ERASES) == erases,
                  "a frame abandoned after %u bytes erased something", i);
            feed(fr, fn);
            f = parse_frame(g_rx, g_rxn);
            check(g_rxn == 18 && f.valid && f.payload[2] == 0x01,
                  "the retry after an idle at %u bytes was not accepted "
                  "(%u bytes back)", i, g_rxn);
        }
        free(fr);
    }
    free(pl);
    free(init);
    free(img);
}

static void t_truncated_then_valid(void)
{
    uint32_t n, i;
    uint8_t *init = mkframe(1, BL_CMD_INIT, 0, 0, &n);
    frame_t f;

    /* Cut the init frame off at every possible point, then send whole ones and
     * count how many it takes to get an answer.
     *
     * REGRESSION. One used NOT to be enough, and that was inherent to a
     * length-driven framer that resynchronised only on the intro marker and
     * discarded everything a bad frame had consumed. The worst case was
     * truncation after 10 bytes: hdr[] is left one byte short, so the NEXT
     * frame's first byte (0x48) becomes the low half of payload_len, giving
     * cmd 0x21 with payload_len 0x0048. The parser then waited for 72 payload
     * bytes plus 4 outro bytes, the outro check landed on a 0x00 in the fifth
     * following frame, and the intro was re-found in the sixth — SIX frames,
     * against the two the hosts send.
     *
     * Both halves of the fix show up here. hdr_plausible() rejects 0x21 with
     * payload_len 0x0048 after 11 bytes, and the rescan then re-finds the
     * intro among the bytes already consumed instead of throwing them away.
     * Every truncation point must now cost exactly one init frame. */
    for (i = 1; i < n; i++) {
        uint32_t tries;
        dev_reset();
        feed(init, i);
        for (tries = 1; tries <= 8; tries++) {
            feed(init, n);
            if (g_rxn) break;
        }
        f = parse_frame(g_rx, g_rxn);
        check(tries == 1 && g_rxn == 24 && f.valid && f.cmd == BL_CMD_INIT,
              "truncation after %u bytes needed %u init frames to resync and "
              "returned %u bytes; the bound is 1 frame / 24 bytes", i, tries,
              g_rxn);
        if (tries > 1) {
            g_resync_cost[i] = tries;
            if (tries > 2)
                warn("a frame truncated after %u bytes costs %u init frames "
                     "to resync; the double-0x21 handshake provides only 2, "
                     "so a truncated write before connect makes TryConnect "
                     "report \"no device found\"", i, tries);
        }
    }

    /* Garbage of every single-byte value between two good frames. */
    for (i = 0; i < 256; i++) {
        uint8_t junk = (uint8_t)i;
        dev_reset();
        feed(init, n);
        feed(&junk, 1);
        feed(init, n);
        f = parse_frame(g_rx, g_rxn);
        check(g_rxn == 24 && f.valid,
              "a 0x%02X byte between frames broke the parser", junk);
    }
    free(init);
}

static void t_oversize_payload(void)
{
    /* A header that claims a payload far larger than the 520-byte buffer. If
     * the length were trusted, this would smash straight through the struct.
     * ASan is watching. */
    uint8_t hdr[11];
    uint8_t filler[4096];
    uint32_t n, i;
    uint8_t *init;
    frame_t f;
    static const uint16_t lens[] = { 521, 600, 1024, 4095, 0x7FFF, 0xFFFF };

    for (i = 0; i < sizeof lens / sizeof lens[0]; i++) {
        dev_reset();
        hdr[0] = 0x48; hdr[1] = 0x48; hdr[2] = 0x4A; hdr[3] = 0x4A;
        hdr[4] = 0x00;
        hdr[5] = 0x00; hdr[6] = 0x01;
        hdr[7] = 0x00; hdr[8] = 0x24;
        hdr[9] = (uint8_t)(lens[i] >> 8); hdr[10] = (uint8_t)lens[i];
        feed(hdr, 11);
        check(g_rxn == 0, "oversize header (len %u) produced output", lens[i]);
        memset(filler, 0x5A, sizeof filler);
        feed(filler, sizeof filler);

        init = mkframe(1, BL_CMD_INIT, 0, 0, &n);
        feed(init, n);
        f = parse_frame(g_rx, g_rxn);
        check(g_rxn == 24 && f.valid,
              "no recovery after an oversize length of %u", lens[i]);
        free(init);
    }

    /* And exactly at the buffer limit: 520 bytes must be accepted by the
     * framer (and then rejected by the data handler, since 520-6=514 > 512). */
    {
        uint8_t *pl = calloc(520, 1);
        dev_reset();
        pl[0] = 0x00; pl[1] = 0x07;              /* index 7 */
        pl[2] = 0x02; pl[3] = 0x02;              /* clen 514 */
        send_frame(9, BL_CMD_DATA, pl, 520);
        f = parse_frame(g_rx, g_rxn);
        check(frame_ok(&f, 9, BL_CMD_DATA) && f.plen == 3
              && f.payload[2] == 0x00,
              "a 520-byte payload with clen 514 should be NAKed");
        free(pl);
    }
}

static void t_odd_and_even_payloads(void)
{
    /* The pad rule is "append one zero byte iff the whole frame is odd", i.e.
     * iff payload_len is even. Feed frames of every payload length from 0..40
     * built by bl_frame_build itself; the parser must consume each one and
     * still answer the init that follows. */
    uint16_t plen;
    uint32_t n;
    uint8_t payload[64];
    uint8_t *init;
    frame_t f;

    memset(payload, 0xA5, sizeof payload);
    for (plen = 0; plen <= 40; plen++) {
        uint32_t fn;
        uint8_t *fr;
        dev_reset();
        /* command 0x77 is unknown: the device must stay silent and stay in
         * sync, whatever the parity of the payload. */
        fr = mkframe(5, 0x0077, payload, plen, &fn);
        check(fn == (uint32_t)(15 + plen + ((15 + plen) & 1)),
              "frame length %u wrong for payload_len %u", fn, plen);
        feed(fr, fn);
        check(g_rxn == 0, "unknown command with payload_len %u answered", plen);
        free(fr);

        init = mkframe(1, BL_CMD_INIT, 0, 0, &n);
        feed(init, n);
        f = parse_frame(g_rx, g_rxn);
        check(g_rxn == 24 && f.valid,
              "lost sync after an unknown command with payload_len %u", plen);
        free(init);
    }
}

static void t_bad_chunk_crc_then_retry(void)
{
    uint32_t imgn;
    uint8_t *img = build_image(0x1000, 0xBEEF, &imgn);
    uint16_t plen;
    uint8_t *pl;
    frame_t f;

    dev_reset();
    send_frame(1, BL_CMD_INIT, 0, 0);

    /* packet 1 with a deliberately wrong chunk CRC */
    pl = mk_data_payload(1, img, 512, 0x1234, -1, &plen);
    send_frame(2, BL_CMD_DATA, pl, plen);
    free(pl);
    f = parse_frame(g_rx, g_rxn);
    check(frame_ok(&f, 2, BL_CMD_DATA) && f.plen == 3
          && be16r(f.payload) == 1 && f.payload[2] == 0x00,
          "a bad chunk CRC must be NAKed with the index echoed");
    check(dev_flash_stat(FS_STAT_ERASES) == 0,
          "a CRC-failed packet must not have erased anything");
    check(dev_proto_stat(DEV_PS_NEXT_INDEX) == 1,
          "a NAKed packet must not advance the expected index");

    /* the retry, correct this time — this is exactly what FlashGBX does */
    pl = mk_data_payload(1, img, 512, -1, -1, &plen);
    send_frame(2, BL_CMD_DATA, pl, plen);
    free(pl);
    f = parse_frame(g_rx, g_rxn);
    check(frame_ok(&f, 2, BL_CMD_DATA) && f.payload[2] == 0x01,
          "the retry of a CRC-failed packet must be accepted");

    /* a lying chunk_len must also be refused, without reading past the frame */
    pl = mk_data_payload(2, img + 512, 512, -1, 500, &plen);
    send_frame(3, BL_CMD_DATA, pl, plen);
    free(pl);
    f = parse_frame(g_rx, g_rxn);
    check(frame_ok(&f, 3, BL_CMD_DATA) && f.payload[2] == 0x00,
          "chunk_len that disagrees with payload_len must be NAKed");

    check(dev_bootloader_intact(), "bootloader region modified during NAK tests");
    free(img);
}

static void t_index_order(void)
{
    uint32_t imgn;
    uint8_t *img = build_image(0x1000, 0x1234, &imgn);   /* 0x1200 total, 9 pkts */
    uint16_t plen;
    uint8_t *pl;
    frame_t f;
    uint32_t erases_before;

    dev_reset();
    send_frame(1, BL_CMD_INIT, 0, 0);

    /* index 0 */
    pl = mk_data_payload(0, img, 512, -1, -1, &plen);
    send_frame(2, BL_CMD_DATA, pl, plen); free(pl);
    f = parse_frame(g_rx, g_rxn);
    check(f.valid && f.payload[2] == 0x00 && be16r(f.payload) == 0,
          "index 0 must be NAKed");

    /* jumping straight to index 2 before index 1 */
    pl = mk_data_payload(2, img + 512, 512, -1, -1, &plen);
    send_frame(3, BL_CMD_DATA, pl, plen); free(pl);
    f = parse_frame(g_rx, g_rxn);
    check(f.valid && f.payload[2] == 0x00, "out-of-order index 2 must be NAKed");
    check(dev_flash_stat(FS_STAT_PROGRAMS) == 0,
          "an out-of-order packet must not program flash");

    /* index 1, then repeat it verbatim — the ack must repeat too, and nothing
     * may be written a second time (a re-write would double-count the
     * streaming image CRC). */
    pl = mk_data_payload(1, img, 512, -1, -1, &plen);
    send_frame(4, BL_CMD_DATA, pl, plen);
    f = parse_frame(g_rx, g_rxn);
    check(f.valid && f.payload[2] == 0x01, "index 1 should be accepted");
    erases_before = dev_flash_stat(FS_STAT_ERASES);
    send_frame(5, BL_CMD_DATA, pl, plen);
    free(pl);
    f = parse_frame(g_rx, g_rxn);
    check(f.valid && f.payload[2] == 0x01 && be16r(f.payload) == 1,
          "a verbatim retransmit of the last packet must be re-acked");
    check(dev_flash_stat(FS_STAT_ERASES) == erases_before,
          "a retransmit must not re-erase");
    check(dev_proto_stat(DEV_PS_BYTES) == 512,
          "a retransmit must not be counted twice (bytes=%u)",
          dev_proto_stat(DEV_PS_BYTES));

    /* a far-future index */
    pl = mk_data_payload(500, img, 512, -1, -1, &plen);
    send_frame(6, BL_CMD_DATA, pl, plen); free(pl);
    f = parse_frame(g_rx, g_rxn);
    check(f.valid && f.payload[2] == 0x00, "index 500 must be NAKed");

    /* an index whose destination would run past the accepted image window */
    pl = mk_data_payload(61, img, 512, -1, -1, &plen);
    send_frame(7, BL_CMD_DATA, pl, plen); free(pl);
    f = parse_frame(g_rx, g_rxn);
    check(f.valid && f.payload[2] == 0x00, "index 61 (past the window) must be NAKed");

    check(dev_bootloader_intact(), "bootloader region modified during index tests");
    check(dev_flash_stat(FS_STAT_FLOOR_HITS) == 0, "a write below 0x3E00 was attempted");
    free(img);
}

static void t_finalize_paths(void)
{
    uint32_t imgn;
    uint8_t *img = build_image(0x1000, 0x77, &imgn);
    frame_t f;
    uint8_t pl[4];
    uint16_t c;

    /* (a) finalize before anything */
    dev_reset();
    send_frame(1, BL_CMD_INIT, 0, 0);
    c = crc16(img, imgn);
    pl[0] = (uint8_t)(c >> 8); pl[1] = (uint8_t)c;
    pl[2] = (uint8_t)(~c >> 8); pl[3] = (uint8_t)(~c);
    send_frame(2, BL_CMD_FINALIZE, pl, 4);
    f = parse_frame(g_rx, g_rxn);
    check(frame_ok(&f, 2, BL_CMD_FINALIZE) && f.plen == 1 && f.payload[0] == 0,
          "finalize with no data must fail");
    check(!dev_finalized(), "device must not consider itself finalized");

    /* (b) full run but a wrong image CRC */
    dev_reset();
    {
        uint32_t npkt = (imgn + 511u) / 512u, k;
        uint16_t seq = 2, plen2;
        send_frame(1, BL_CMD_INIT, 0, 0);
        for (k = 1; k <= npkt; k++) {
            uint32_t off = (k - 1u) * 512u;
            uint16_t clen = (uint16_t)((imgn - off > 512u) ? 512u : (imgn - off));
            uint8_t *p2 = mk_data_payload((uint16_t)k, img + off, clen, -1, -1,
                                          &plen2);
            send_frame(seq, BL_CMD_DATA, p2, plen2);
            free(p2);
            seq++;
        }
        c = (uint16_t)(crc16(img, imgn) ^ 0x0001u);
        pl[0] = (uint8_t)(c >> 8); pl[1] = (uint8_t)c;
        pl[2] = (uint8_t)(~c >> 8); pl[3] = (uint8_t)(~c);
        send_frame(seq, BL_CMD_FINALIZE, pl, 4);
        f = parse_frame(g_rx, g_rxn);
        check(f.valid && f.payload[0] == 0x00,
              "finalize with the wrong image CRC must fail");
        check(!dev_finalized(), "a wrong image CRC must not finalize");
        /* The boot-info record must NOT have been committed: header CRC word
         * still erased means the boot decision rejects the app and the device
         * stays in update mode. That is the fail-safe. */
        {
            uint8_t h[16];
            dev_flash_read(0x3E00u, h, 16);
            check(h[12] == 0xFF && h[13] == 0xFF,
                  "the boot-info header CRC was committed despite a failed "
                  "finalize (0x%02X%02X) — an interrupted update would boot",
                  h[13], h[12]);
        }

        /* (c) the same session, now with the right CRC — must succeed */
        c = crc16(img, imgn);
        pl[0] = (uint8_t)(c >> 8); pl[1] = (uint8_t)c;
        pl[2] = (uint8_t)(~c >> 8); pl[3] = (uint8_t)(~c);
        send_frame(seq, BL_CMD_FINALIZE, pl, 4);
        f = parse_frame(g_rx, g_rxn);
        check(f.valid && f.payload[0] == 0x01,
              "finalize with the correct CRC after a failed one must succeed");
        check(flash_equals(0x3E00u, img, imgn), "image mismatch after finalize");

        /* (d) idempotent re-finalize */
        send_frame((uint16_t)(seq + 1u), BL_CMD_FINALIZE, pl, 4);
        f = parse_frame(g_rx, g_rxn);
        check(f.valid && f.payload[0] == 0x01, "re-finalize must be re-acked");
    }

    /* (e) inverse field that is not the inverse */
    dev_reset();
    send_frame(1, BL_CMD_INIT, 0, 0);
    c = crc16(img, imgn);
    pl[0] = (uint8_t)(c >> 8); pl[1] = (uint8_t)c;
    pl[2] = (uint8_t)(c >> 8); pl[3] = (uint8_t)c;      /* not inverted */
    send_frame(2, BL_CMD_FINALIZE, pl, 4);
    f = parse_frame(g_rx, g_rxn);
    check(f.valid && f.payload[0] == 0x00,
          "finalize with a bad inverse field must fail");

    /* (f) short finalize payload — documented as "no response at all" */
    dev_reset();
    send_frame(1, BL_CMD_INIT, 0, 0);
    send_frame(2, BL_CMD_FINALIZE, pl, 2);
    check(g_rxn == 0,
          "a 2-byte finalize payload produced %u response bytes; the module "
          "documents silence here", g_rxn);

    free(img);
}

static void t_image_shapes(void)
{
    struct { uint32_t applen; int expect; const char *what; } cases[] = {
        /* A 4-byte "application" USED to be answered 0x01 SUCCESS here, and
         * bl_app_valid() would then refuse to boot it forever — the device
         * sits in update mode reporting a successful update. The updater now
         * shares the validator's BL_APP_MIN_LEN, so it is refused at finalize
         * (-2) instead, before any boot-info record is committed. */
        { 0x0004, -2, "a 4-byte app is below BL_APP_MIN_LEN" },
        { BL_APP_MIN_LEN - 4u, -2, "four bytes below BL_APP_MIN_LEN" },
        { BL_APP_MIN_LEN, 0, "exactly BL_APP_MIN_LEN (a full vector table)" },
        { 0x0123, 0, "app length not a multiple of 4 (unaligned tail)" },
        { 0x0200, 0, "app exactly one sector" },
        { 0x7520, 0, "the real L15 payload length" },
        /* 0x7600 was the OLD, defective ceiling — only 224 bytes above the
         * shipping L15 payload, and 8x tighter than boot.c's validator. That
         * divergence was an update-breaking defect (h_data erases the boot-info
         * sector on packet 1 before any total-size limit applies), so the
         * updater now shares the validator's limit. An image a little larger
         * than the current firmware must be ACCEPTED, not refused. */
        { 0x7604, 0, "just above the old 0x7600 ceiling — must now be accepted" },
        { 0x8000, 0, "comfortably larger than any shipped firmware so far" },
        { BL_APP_MAX_LEN, 0, "exactly BL_APP_MAX_LEN" },
        { BL_APP_MAX_LEN + 4u, -1, "four bytes over BL_APP_MAX_LEN" },
    };
    uint32_t i;

    for (i = 0; i < sizeof cases / sizeof cases[0]; i++) {
        uint32_t imgn;
        uint8_t *img = build_image(cases[i].applen, 0x2000u + i, &imgn);
        int r;
        dev_reset();
        r = run_update(img, imgn, 512, 0);
        check(r == cases[i].expect,
              "%s (applen 0x%X): run_update returned %d, expected %d",
              cases[i].what, cases[i].applen, r, cases[i].expect);
        if (cases[i].expect == 0 && r == 0) {
            check(flash_equals(0x3E00u, img, imgn),
                  "%s: flash does not match the image", cases[i].what);
            check(dev_finalized(), "%s: not finalized", cases[i].what);
        }
        check(dev_bootloader_intact(), "%s: bootloader region modified",
              cases[i].what);
        check(dev_flash_stat(FS_STAT_FLOOR_HITS) == 0,
              "%s: write attempted below 0x3E00", cases[i].what);
        check(dev_flash_stat(FS_STAT_VERIFY_FAILS) == 0,
              "%s: programmed over non-erased flash", cases[i].what);
        free(img);
    }
}

static void t_header_validation(void)
{
    /* Corrupt one field of the boot-info record at a time; the image CRC on
     * the wire is recomputed each time, so ONLY the record check can reject
     * it. Each of these must refuse to commit. */
    struct { uint32_t off; uint8_t mask; const char *what; } cases[] = {
        { 2,  0x01, "the \"LFBG\" tag"                     },
        { 6,  0x01, "the stored payload CRC"               },
        { 8,  0x01, "the stored application length"        },
        { 12, 0x01, "the stored header CRC"                },
    };
    uint32_t i;

    for (i = 0; i < sizeof cases / sizeof cases[0]; i++) {
        uint32_t imgn;
        uint8_t *img = build_image(0x800, 0x5150u + i, &imgn);
        int r;
        img[cases[i].off] ^= cases[i].mask;
        dev_reset();
        r = run_update(img, imgn, 512, 0);
        check(r == -2, "a corrupt %s should fail at finalize (got %d)",
              cases[i].what, r);
        {
            uint8_t h[16];
            dev_flash_read(0x3E00u, h, 16);
            check(h[12] == 0xFF && h[13] == 0xFF,
                  "a corrupt %s still committed the header CRC word",
                  cases[i].what);
        }
        free(img);
    }

    /* The marker word is NOT authenticated beyond the record CRC, and
     * docs/DESIGN.md §4 is emphatic that nothing may be stamped over it.
     * Check the accepted values survive the round trip unmodified.
     *
     * 0x1234 IS THE THIRD CASE AND IT IS THE POINT OF THE LIST. hdr_check()
     * used to whitelist {0xFFFF, 0x5555} while bl_app_valid() never looked at
     * the marker at all, so the WRITER WAS STRICTER THAN THE VALIDATOR: an
     * image with any other marker and otherwise perfect CRCs, length, SP and
     * reset vector was answered 0x00 FAIL at finalize — after packet 1 had
     * already erased sector 31 — leaving the device in update mode with no
     * valid application, over an image the boot decision would have accepted.
     * Same defect class as the BL_APP_MIN_LEN and BL_APP_MAX_LEN divergences.
     * The whitelist is gone (the record CRC authenticates the field), the two
     * gate sets are now declared as BL_WRITER_GATES and BL_VALIDATOR_GATES and
     * asserted equal wherever both headers are included, and this case is what
     * fails if the whitelist ever comes back on one side only. */
    {
        uint16_t markers[3] = { 0xFFFFu, 0x5555u, 0x1234u };
        uint32_t k;
        for (k = 0; k < 3; k++) {
            uint32_t imgn;
            uint8_t *img = build_image(0x800, 0x9000u + k, &imgn);
            uint16_t hcrc;
            uint8_t h[16];
            int r;
            img[0] = (uint8_t)markers[k];
            img[1] = (uint8_t)(markers[k] >> 8);
            hcrc = crc16(img, 12);
            img[12] = (uint8_t)hcrc; img[13] = (uint8_t)(hcrc >> 8);
            dev_reset();
            r = run_update(img, imgn, 512, 0);
            check(r == 0, "marker 0x%04X should be accepted (got %d)",
                  markers[k], r);
            dev_flash_read(0x3E00u, h, 2);
            check(h[0] == img[0] && h[1] == img[1],
                  "marker 0x%04X was rewritten to 0x%02X%02X — nothing may be "
                  "stamped over it", markers[k], h[1], h[0]);
            free(img);
        }
    }
}

static void t_interrupted_update(void)
{
    /* Cut the session off after the first data packet. The boot-info sector
     * must already have been erased (so no stale record can boot a
     * half-written app) and nothing may be committed. */
    uint32_t imgn;
    uint8_t *img = build_image(0x1000, 0x4242, &imgn);
    uint8_t h[16];
    uint32_t j, ff = 0;

    dev_reset();
    run_update(img, imgn, 512, 1);
    check(dev_proto_stat(DEV_PS_ERASED_HDR) == 1,
          "sector 31 must be erased on the first data packet");
    dev_flash_read(0x3E00u, h, 16);
    for (j = 0; j < 16; j++) if (h[j] == 0xFF) ff++;
    check(ff == 16, "the boot-info record is not blank after packet 1 "
          "(%u/16 bytes erased) — an interrupted update could boot", ff);
    check(!dev_finalized(), "an interrupted update must not be finalized");
    check(dev_bootloader_intact(), "bootloader region modified");
    free(img);
}

static void t_no_flash_driver(void)
{
    /* ops == NULL: the module must degrade to NAKs rather than dereference a
     * null function pointer. This is the state boot.c leaves it in if a future
     * refactor forgets bl_proto_bind(). */
    uint32_t imgn;
    uint8_t *img = build_image(0x400, 0x31337, &imgn);
    frame_t f;
    uint16_t plen;
    uint8_t *pl;

    dev_reset_nullops();
    send_frame(1, BL_CMD_INIT, 0, 0);
    f = parse_frame(g_rx, g_rxn);
    check(frame_ok(&f, 1, BL_CMD_INIT), "init must work without a flash driver");
    pl = mk_data_payload(1, img, 512, -1, -1, &plen);
    send_frame(2, BL_CMD_DATA, pl, plen);
    free(pl);
    f = parse_frame(g_rx, g_rxn);
    check(f.valid && f.plen == 3 && f.payload[2] == 0x00,
          "a data packet with no flash driver must be NAKed, not crash");

    /* Carry the session all the way through finalize rather than stopping at
     * the first NAK: the finalize path is where commit_header() would
     * dereference ops->program, and it is reached whatever the data packets
     * did. Nothing may be written, nothing may be reported as committed, and
     * the modelled bootloader must be untouched. */
    {
        uint16_t c = crc16(img, imgn);
        uint8_t p4[4];
        p4[0] = (uint8_t)(c >> 8); p4[1] = (uint8_t)c;
        p4[2] = (uint8_t)(~c >> 8); p4[3] = (uint8_t)(~c);
        send_frame(3, BL_CMD_FINALIZE, p4, 4);
        f = parse_frame(g_rx, g_rxn);
        check(frame_ok(&f, 3, BL_CMD_FINALIZE) && f.plen == 1
              && f.payload[0] == 0x00,
              "finalize with no flash driver must be NAKed, not crash");
        check(!dev_finalized(),
              "the device claimed to be finalized with no flash driver");
    }
    check(dev_bootloader_intact(),
          "the bootloader region was modified with no flash driver bound");
    check(dev_flash_stat(FS_STAT_ERASES) == 0
          && dev_flash_stat(FS_STAT_PROGRAMS) == 0
          && dev_flash_stat(FS_STAT_READS) == 0,
          "the flash model was touched despite ops == NULL "
          "(%u erases, %u programs, %u reads)",
          dev_flash_stat(FS_STAT_ERASES), dev_flash_stat(FS_STAT_PROGRAMS),
          dev_flash_stat(FS_STAT_READS));
    check(commit_word_blank(),
          "the boot-info commit word is not blank with no flash driver");
    free(img);
}

static void t_no_readback_op(void)
{
    /* read == NULL: per-packet verification and flash_verify() are skipped.
     * The update must still complete and still produce the right bytes. */
    uint32_t imgn;
    uint8_t *img = build_image(0x900, 0x515, &imgn);
    int r;

    dev_reset_noread();
    r = run_update(img, imgn, 512, 0);
    check(r == 0, "update with no read-back op returned %d", r);
    check(flash_equals(0x3E00u, img, imgn),
          "image mismatch with no read-back op");
    check(dev_flash_stat(FS_STAT_READS) == 0,
          "the device read flash despite a NULL read op");
    free(img);
}

static void t_intro_inside_payload(void)
{
    /* A chunk whose bytes contain the intro marker must not cause a mid-frame
     * resync — the framer is length-driven once it is past the header. */
    uint32_t imgn;
    uint8_t *img = build_image(0x600, 0xABCD, &imgn);
    int r;
    uint32_t i;

    for (i = 0x210; i < 0x260; i += 8) {
        img[i + 0] = 0x48; img[i + 1] = 0x48; img[i + 2] = 0x4A; img[i + 3] = 0x4A;
        img[i + 4] = 0x4A; img[i + 5] = 0x4A; img[i + 6] = 0x48; img[i + 7] = 0x48;
    }
    /* rebuild the CRCs over the doctored payload */
    {
        uint16_t appcrc = crc16(img + 0x200, imgn - 0x200);
        uint16_t hcrc;
        img[6] = (uint8_t)appcrc; img[7] = (uint8_t)(appcrc >> 8);
        hcrc = crc16(img, 12);
        img[12] = (uint8_t)hcrc; img[13] = (uint8_t)(hcrc >> 8);
    }
    dev_reset();
    r = run_update(img, imgn, 512, 0);
    check(r == 0, "an image containing intro/outro markers failed (%d)", r);
    check(flash_equals(0x3E00u, img, imgn),
          "image containing markers was not stored correctly");
    free(img);
}

static void t_data_without_init(void)
{
    /* Neither host would do this, but the state machine must be usable from a
     * cold reset with no 0x21 — bl_proto_reset() already establishes the
     * session. */
    uint32_t imgn;
    uint8_t *img = build_image(0x400, 0x2468, &imgn);
    uint16_t plen;
    uint8_t *pl;
    frame_t f;

    dev_reset();
    pl = mk_data_payload(1, img, 512, -1, -1, &plen);
    send_frame(2, BL_CMD_DATA, pl, plen);
    free(pl);
    f = parse_frame(g_rx, g_rxn);
    check(f.valid && f.payload[2] == 0x01,
          "a data packet before any init should still be accepted");
    free(img);
}

static void t_init_midsession(void)
{
    /* 0x21 resets the session. Confirm it really does, and confirm it touches
     * no flash (documented behaviour, and the reason a host that gave up can
     * simply start over). */
    uint32_t imgn;
    uint8_t *img = build_image(0x400, 0x1111, &imgn);
    uint16_t plen;
    uint8_t *pl;
    uint32_t erases;
    frame_t f;

    dev_reset();
    send_frame(1, BL_CMD_INIT, 0, 0);
    pl = mk_data_payload(1, img, 512, -1, -1, &plen);
    send_frame(2, BL_CMD_DATA, pl, plen);
    erases = dev_flash_stat(FS_STAT_ERASES);
    check(dev_proto_stat(DEV_PS_NEXT_INDEX) == 2, "index should have advanced");

    send_frame(1, BL_CMD_INIT, 0, 0);
    check(dev_proto_stat(DEV_PS_NEXT_INDEX) == 1, "0x21 should reset the index");
    check(dev_flash_stat(FS_STAT_ERASES) == erases, "0x21 must not touch flash");

    /* and the session genuinely restarts */
    send_frame(2, BL_CMD_DATA, pl, plen);
    free(pl);
    f = parse_frame(g_rx, g_rxn);
    check(f.valid && f.payload[2] == 0x01, "packet 1 after a re-init failed");
    free(img);
}

/* ------------------------------------------------------------------ */
/* Defect 4: the edge src/boot.c infers a session restart from          */
/* ------------------------------------------------------------------ */

static void t_finalized_cleared_by_init(void)
{
    /* bl_update_mode() clears its `armed` and `refused` flags when it sees
     *     (armed || refused) && !bl_proto_finalized(&bl_update_proto)
     * and calls that "a 0x21 restarted the session under us". The inference is
     * only sound because of three facts, none of which proto.h states as an
     * interface guarantee and all three of which live in proto.c:
     *
     *   1. bl_proto_finalized() goes TRUE only on a committed finalize;
     *   2. h_init() -> session_reset() clears it again, so a 0x21 on an
     *      already-open port pulls it back to FALSE;
     *   3. nothing ELSE pulls it back to false mid-session — otherwise
     *      bl_update_mode() would disarm on an ordinary NAK and the handover
     *      it exists to perform would never fire.
     *
     * boot.c's bl_update_mode() body is compiled out of the host harness
     * (-DBL_HOST_TEST), so the fix itself cannot be exercised natively. What
     * CAN be pinned natively is the proto.c behaviour the fix reads, which is
     * where a silent regression would actually come from: this test fails if
     * proto.c ever stops clearing `finalized` on 0x21 (defect 4 returns), and
     * equally if it ever starts clearing it on something else (boot.c would
     * abort a live handover). */
    uint32_t imgn;
    uint8_t *img = build_image(0x800, 0xD4D4, &imgn);
    uint16_t plen;
    uint8_t *pl;
    frame_t f;

    dev_reset();
    check(!dev_finalized(), "a fresh device must not report finalized");
    check(run_update(img, imgn, 512, 0) == 0, "setup update failed");
    check(dev_finalized(), "fact 1: a committed finalize must report finalized");

    /* Fact 3 first, because it is the one an over-eager fix would break. A
     * NAKed data packet after finalize, an idle notification, and a refused
     * re-finalize are all things FlashGBX can produce on a still-open port
     * between the 0x01 SUCCESS and the settle window expiring. None of them is
     * a session restart, and if any cleared `finalized` boot.c would disarm
     * and the device would never hand over. */
    pl = mk_data_payload(1, img, 512, -1, -1, &plen);
    send_frame(99, BL_CMD_DATA, pl, plen);
    f = parse_frame(g_rx, g_rxn);
    check(f.valid && f.plen == 3 && f.payload[2] == 0x00,
          "setup: the late data packet should have been NAKed");
    check(dev_finalized(), "fact 3: a NAKed data packet cleared finalized");

    {
        uint8_t idle[64];
        (void)dev_idle(idle, sizeof idle);
        check(dev_finalized(), "fact 3: an idle notification cleared finalized");
    }
    {
        uint16_t c = (uint16_t)(crc16(img, imgn) ^ 0x55AAu);
        uint8_t p4[4];
        p4[0] = (uint8_t)(c >> 8); p4[1] = (uint8_t)c;
        p4[2] = (uint8_t)(~c >> 8); p4[3] = (uint8_t)(~c);
        send_frame(100, BL_CMD_FINALIZE, p4, 4);
        f = parse_frame(g_rx, g_rxn);
        check(f.valid && f.plen == 1 && f.payload[0] == 0x00,
              "setup: the wrong-CRC re-finalize should have been refused");
        check(dev_finalized(), "fact 3: a refused re-finalize cleared finalized");
    }
    /* Bytes that do not form a frame at all, and a stray trigger byte: the
     * resync path must not look like a session restart either. */
    {
        static const uint8_t junk[] = { 0x00, 0xFF, 0x5A, 0x21, 0x21, 0x00 };
        feed(junk, sizeof junk);
        check(dev_finalized(), "fact 3: junk bytes cleared finalized");
    }

    /* Fact 2 — the edge itself. A well-formed 0x21 on the SAME open port,
     * which is exactly what a host that reconnects without closing the tty
     * sends, and exactly the case defect 4's two bad outcomes came from. */
    send_frame(1, BL_CMD_INIT, 0, 0);
    f = parse_frame(g_rx, g_rxn);
    check(frame_ok(&f, 1, BL_CMD_INIT),
          "the second 0x21 was not answered");
    check(!dev_finalized(),
          "fact 2: a 0x21 init frame must clear finalized — boot.c reads this "
          "edge to disarm a stale settle window (defect 4)");

    /* And it must STAY clear across the whole second update, right up to the
     * new commit: boot.c must not re-arm on the strength of the OLD image
     * while the new one is being written. */
    {
        uint32_t k, npkt = (imgn + 511u) / 512u;
        uint16_t seq = 2;
        for (k = 1; k <= npkt; k++) {
            uint32_t off = (k - 1u) * 512u;
            uint16_t clen = (uint16_t)((imgn - off > 512u) ? 512u : (imgn - off));
            uint16_t p2;
            uint8_t *q = mk_data_payload((uint16_t)k, img + off, clen, -1, -1, &p2);
            send_frame(seq++, BL_CMD_DATA, q, p2);
            free(q);
            f = parse_frame(g_rx, g_rxn);
            check(f.valid && f.plen == 3 && f.payload[2] == 0x01,
                  "second-update packet %u was NAKed", k);
            if (dev_finalized()) {
                check(0, "finalized came back TRUE at packet %u of the "
                         "second update, before its finalize", k);
                break;
            }
        }
        {
            uint16_t c = crc16(img, imgn);
            uint8_t p4[4];
            p4[0] = (uint8_t)(c >> 8); p4[1] = (uint8_t)c;
            p4[2] = (uint8_t)(~c >> 8); p4[3] = (uint8_t)(~c);
            send_frame(seq, BL_CMD_FINALIZE, p4, 4);
            f = parse_frame(g_rx, g_rxn);
            check(f.valid && f.plen == 1 && f.payload[0] == 0x01,
                  "the second update's finalize was refused");
        }
        check(dev_finalized(),
              "the second update finalized but the device does not say so");
        check(flash_equals(0x3E00u, img, imgn),
              "the second update did not leave the image intact");
        check(dev_bootloader_intact(),
              "the second update touched flash below 0x3E00");
    }
    free(pl);
    free(img);
}

static void t_page_size_contract(void)
{
    /* The device advertises page_size 0x200 and both hosts obey it. A host
     * that chunked at 0x400 anyway must be refused, not silently mis-written
     * (its packet 2 would land 0x200 short of where the device expects). */
    uint32_t imgn;
    uint8_t *img = build_image(0x1000, 0x808, &imgn);
    frame_t f;
    uint16_t plen;
    uint8_t *pl;

    dev_reset();
    send_frame(1, BL_CMD_INIT, 0, 0);
    pl = mk_data_payload(1, img, 513, -1, -1, &plen);   /* > page_size */
    send_frame(2, BL_CMD_DATA, pl, plen);
    free(pl);
    f = parse_frame(g_rx, g_rxn);
    check(f.valid && f.payload[2] == 0x00,
          "a chunk larger than the advertised page_size must be NAKed");

    /* A short first chunk is also refused: packet 1 must be a whole
     * boot-info sector. */
    dev_reset();
    send_frame(1, BL_CMD_INIT, 0, 0);
    pl = mk_data_payload(1, img, 256, -1, -1, &plen);
    send_frame(2, BL_CMD_DATA, pl, plen);
    free(pl);
    f = parse_frame(g_rx, g_rxn);
    check(f.valid && f.payload[2] == 0x00,
          "a short packet 1 must be NAKed");

    /* clen == 0 */
    dev_reset();
    send_frame(1, BL_CMD_INIT, 0, 0);
    {
        uint8_t p6[6] = { 0x00, 0x01, 0x00, 0x00, 0xFF, 0xFF };
        send_frame(2, BL_CMD_DATA, p6, 6);
        f = parse_frame(g_rx, g_rxn);
        check(f.valid && f.payload[2] == 0x00, "clen 0 must be NAKed");
    }
    /* payload too short to carry an index at all: documented silence */
    {
        uint8_t p5[5] = { 0, 1, 0, 0, 0 };
        dev_reset();
        send_frame(2, BL_CMD_DATA, p5, 5);
        check(g_rxn == 0,
              "a 5-byte data payload produced %u bytes; the module documents "
              "silence (a real host cannot produce this)", g_rxn);
    }
    free(img);
}

/* ------------------------------------------------------------------ */
/* Flash that misbehaves                                               */
/* ------------------------------------------------------------------ */

/* Exhaustive single-fault sweep.
 *
 * The stub could not fail before this, so proto.c's whole flash-failure family
 * — NAK on a failed erase, NAK on a failed program, NAK on a read-back
 * mismatch, a failed boot-info commit — was dead code in the harness. Those
 * are precisely the paths that decide what a device with one marginal sector
 * ends up holding.
 *
 * Rather than guess which call indices are interesting, inject at EVERY one:
 * every erase, every programmed word, every read, in four flavours. What is
 * asserted is the safety invariant itself, in the form that survives the
 * commit-window asymmetry documented in commit_header():
 *
 *   the device never reports success it did not achieve, and never leaves a
 *   VALID boot-info record unless the image on flash is byte-for-byte the one
 *   the host sent.
 *
 * Failures are counted through the loop and asserted once at the end, so the
 * assertion count stays honest instead of being multiplied by the sweep.
 */
struct fault_tally {
    uint32_t cases, never_fired, reported_success, claimed_final;
    uint32_t unsafe_commit, bootloader_hit, floor_hit, contract;
    uint32_t committed_but_correct;
};

static void sweep_fault(fs_fault_t what, uint32_t from, uint32_t to,
                        struct fault_tally *t)
{
    uint32_t nth;
    for (nth = from; nth <= to; nth++) {
        uint32_t imgn;
        uint8_t *img = build_image(0x800, 0xF00D, &imgn);
        int r;

        dev_reset();
        fs_inject(what, nth);
        r = run_update(img, imgn, 512, 0);

        t->cases++;
        if (dev_flash_stat(FS_STAT_INJECTED) != 1) t->never_fired++;
        if (r == 0)                                t->reported_success++;
        if (dev_finalized())                       t->claimed_final++;
        if (!commit_word_blank()) {
            /* A live record is only acceptable if it describes exactly the
             * image the host sent — the commit-word read-back window. */
            if (flash_equals(0x3E00u, img, imgn)) t->committed_but_correct++;
            else                                  t->unsafe_commit++;
        }
        if (!dev_bootloader_intact())                   t->bootloader_hit++;
        if (dev_flash_stat(FS_STAT_FLOOR_HITS) != 0)    t->floor_hit++;
        if (dev_flash_stat(FS_STAT_VIOLATIONS) != 0)    t->contract++;
        free(img);
    }
}

static void t_flash_failures(void)
{
    uint32_t imgn;
    uint8_t *img = build_image(0x800, 0xF00D, &imgn);
    uint32_t prog_words, reads, erases;
    struct fault_tally t;
    frame_t f;

    /* Baseline: exactly how many of each operation a clean run of this image
     * performs, so the sweep can cover all of them and none beyond. */
    dev_reset();
    check(run_update(img, imgn, 512, 0) == 0, "baseline update failed");
    prog_words = dev_flash_stat(FS_STAT_PROG_BYTES) / 4u;
    reads      = dev_flash_stat(FS_STAT_READS);
    erases     = dev_flash_stat(FS_STAT_ERASES);
    free(img);
    check(prog_words > 4u && reads > 2u && erases > 1u,
          "baseline counts look wrong (%u words, %u reads, %u erases)",
          prog_words, reads, erases);

    memset(&t, 0, sizeof t);
    sweep_fault(FS_FAULT_ERASE,        1, erases,     &t);
    sweep_fault(FS_FAULT_PROGRAM,      1, prog_words, &t);
    sweep_fault(FS_FAULT_READ,         1, reads,      &t);
    sweep_fault(FS_FAULT_READ_CORRUPT, 1, reads,      &t);

    check(t.never_fired == 0,
          "%u of %u injected faults never fired — those cases proved nothing",
          t.never_fired, t.cases);
    check(t.reported_success == 0,
          "%u of %u single flash faults were reported to the host as a "
          "successful update", t.reported_success, t.cases);
    check(t.claimed_final == 0,
          "%u of %u single flash faults left the device believing it was "
          "finalized", t.claimed_final, t.cases);
    check(t.unsafe_commit == 0,
          "%u of %u single flash faults left a VALID boot-info record over an "
          "image that is not what the host sent — the device would boot a "
          "half-written application", t.unsafe_commit, t.cases);
    check(t.bootloader_hit == 0,
          "%u of %u single flash faults modified the region below 0x3E00",
          t.bootloader_hit, t.cases);
    check(t.floor_hit == 0,
          "%u of %u single flash faults attempted a write below 0x3E00",
          t.floor_hit, t.cases);
    check(t.contract == 0,
          "%u of %u single flash faults violated the flash driver contract",
          t.contract, t.cases);
    printf("  single-fault sweep: %u cases (%u erases, %u program words, "
           "%u reads x2), all NAKed; %u left a valid record, every one of them "
           "over a byte-identical image (the commit-word read-back window "
           "documented in commit_header())\n",
           t.cases, erases, prog_words, reads, t.committed_but_correct);

    /* And a directed case for the one that matters most: the commit word
     * itself refusing to take. The record must stay invalid AND the device
     * must answer 0x00. */
    {
        uint32_t n2;
        uint8_t *img2 = build_image(0x800, 0xF00D, &n2);
        int r;
        dev_reset();
        fs_inject(FS_FAULT_PROGRAM, prog_words);
        r = run_update(img2, n2, 512, 0);
        check(r == -2, "a failing commit word should NAK the finalize (%d)", r);
        check(commit_word_blank(),
              "a failing commit word still left a valid boot-info record");
        check(!dev_finalized(), "a failing commit word reported finalized");
        /* The host's natural response is to finalize again. With the fault
         * one-shot and now spent, the retry must succeed. */
        {
            uint16_t c = crc16(img2, n2);
            uint8_t p4[4];
            p4[0] = (uint8_t)(c >> 8); p4[1] = (uint8_t)c;
            p4[2] = (uint8_t)(~c >> 8); p4[3] = (uint8_t)(~c);
            send_frame(200, BL_CMD_FINALIZE, p4, 4);
            f = parse_frame(g_rx, g_rxn);
            check(f.valid && f.plen == 1 && f.payload[0] == 0x01,
                  "the finalize retry after a transient commit failure was "
                  "refused");
            check(flash_equals(0x3E00u, img2, n2),
                  "the image is wrong after a retried commit");
            check(!commit_word_blank(),
                  "the retried commit did not write the header CRC word");
        }
        free(img2);
    }
}

static void t_app_sp_gate(void)
{
    /* proto.c's flash_verify() applies the same "the initial stack pointer
     * must look like SRAM" test the boot decision does, so the updater never
     * commits a record for an image boot.c would afterwards refuse.
     *
     * This is not hypothetical: an application accidentally linked for base
     * 0x0000 — exactly the layout a bootloader-less GBFlash ships with — is
     * the [bricks-device] defect already fixed in boot.c. Its first word is a
     * vector-table entry, not a stack pointer. Every test image before this
     * one wrote 0x20008000 there, so the gate had never been made to fail. */
    static const uint32_t bad_sp[] = {
        0x000000A5u,   /* a Thumb code address: the base-0x0000 link */
        0x00000000u,
        0x08000400u,   /* flash-shaped */
        0xFFFFFFFFu,
        0x2FFE0000u    /* one bit outside the accepted SRAM window */
    };
    uint32_t i;

    for (i = 0; i < sizeof bad_sp / sizeof bad_sp[0]; i++) {
        uint32_t imgn;
        uint8_t *img = build_image(0x800, 0xA5A5u + i, &imgn);
        uint16_t appcrc, hcrc;
        int r;

        img[0x200] = (uint8_t)bad_sp[i];
        img[0x201] = (uint8_t)(bad_sp[i] >> 8);
        img[0x202] = (uint8_t)(bad_sp[i] >> 16);
        img[0x203] = (uint8_t)(bad_sp[i] >> 24);
        /* Everything else about the image stays perfectly consistent, so only
         * the SP test can reject it. */
        appcrc = crc16(img + 0x200, imgn - 0x200);
        img[6] = (uint8_t)appcrc; img[7] = (uint8_t)(appcrc >> 8);
        hcrc = crc16(img, 12);
        img[12] = (uint8_t)hcrc; img[13] = (uint8_t)(hcrc >> 8);

        dev_reset();
        r = run_update(img, imgn, 512, 0);
        check(r == -2, "an application whose initial SP is 0x%08X should be "
              "refused at finalize (got %d)", bad_sp[i], r);
        check(commit_word_blank(),
              "an application whose initial SP is 0x%08X was committed anyway",
              bad_sp[i]);
        free(img);
    }

    /* The boundaries of the accepted window, so the gate cannot quietly
     * become "accept everything". */
    {
        static const uint32_t good_sp[] = { 0x20000000u, 0x20008000u,
                                            0x2001FFFCu };
        uint32_t k;
        for (k = 0; k < sizeof good_sp / sizeof good_sp[0]; k++) {
            uint32_t imgn;
            uint8_t *img = build_image(0x800, 0xB0B0u + k, &imgn);
            uint16_t appcrc, hcrc;
            int r;
            img[0x200] = (uint8_t)good_sp[k];
            img[0x201] = (uint8_t)(good_sp[k] >> 8);
            img[0x202] = (uint8_t)(good_sp[k] >> 16);
            img[0x203] = (uint8_t)(good_sp[k] >> 24);
            appcrc = crc16(img + 0x200, imgn - 0x200);
            img[6] = (uint8_t)appcrc; img[7] = (uint8_t)(appcrc >> 8);
            hcrc = crc16(img, 12);
            img[12] = (uint8_t)hcrc; img[13] = (uint8_t)(hcrc >> 8);
            dev_reset();
            r = run_update(img, imgn, 512, 0);
            check(r == 0, "an SRAM-shaped SP of 0x%08X was refused (%d)",
                  good_sp[k], r);
            free(img);
        }
    }
}

/* ------------------------------------------------------------------ */
/* Defect 3: the finalize-time validator must be neither stricter nor  */
/* looser than the boot-time one.                                      */
/* ------------------------------------------------------------------ */

/* Rewrite the application's reset vector (image offset 0x204) and repair every
 * CRC around it, so ONLY the vector-table gate can decide the outcome. */
static uint8_t *image_with_reset_vector(uint32_t applen, uint32_t seed,
                                        uint32_t rv, uint32_t *out_len)
{
    uint8_t *img = build_image(applen, seed, out_len);
    uint16_t appcrc, hcrc;
    img[0x204] = (uint8_t)rv;         img[0x205] = (uint8_t)(rv >> 8);
    img[0x206] = (uint8_t)(rv >> 16); img[0x207] = (uint8_t)(rv >> 24);
    appcrc = crc16(img + 0x200, *out_len - 0x200);
    img[6] = (uint8_t)appcrc; img[7] = (uint8_t)(appcrc >> 8);
    hcrc = crc16(img, 12);
    img[12] = (uint8_t)hcrc; img[13] = (uint8_t)(hcrc >> 8);
    return img;
}

static void t_app_reset_vector_gate(void)
{
    /* bl_app_valid() step 4b refuses an application whose reset vector is not
     * a Thumb pointer inside the image. Finalize had no counterpart, so the
     * device could answer 0x01 SUCCESS, commit the record, and then refuse to
     * boot the image it had just declared good — sitting in update mode after
     * a "successful" update, exactly the asymmetry proto.h:46-67 was widened
     * once before to remove.
     *
     * The application payload here is 0x800 bytes, so the accepted window is
     * [0x4000, 0x4800). */
    static const struct { uint32_t rv; const char *why; } bad[] = {
        { 0x00004008u, "Thumb bit clear (an even vector HardFaults instantly)" },
        { 0x000040A4u, "Thumb bit clear, otherwise a plausible entry point" },
        { 0x00000000u, "erased/zero vector" },
        { 0x000000A5u, "the base-0x0000 link: Thumb, but far below the image" },
        { 0x00003E01u, "points into the BOOT-INFO page, below the app" },
        { 0x00003FFFu, "one byte below BL_APP_BASE" },
        { 0x00004801u, "one word past the end of a 0x800-byte app" },
        { 0x0000C001u, "past the image entirely" },
        { 0x20000001u, "an SRAM address, not code" },
        { 0xFFFFFFFFu, "erased flash" }
    };
    static const struct { uint32_t rv; const char *why; } good[] = {
        { 0x00004001u, "the first byte of the application" },
        { 0x000040A5u, "the real firmware's own reset vector" },
        { 0x000047FFu, "the last halfword inside a 0x800-byte app" }
    };
    uint32_t i;

    for (i = 0; i < sizeof bad / sizeof bad[0]; i++) {
        uint32_t imgn;
        uint8_t *img = image_with_reset_vector(0x800, 0xE1E1u + i, bad[i].rv,
                                               &imgn);
        int r;
        dev_reset();
        r = run_update(img, imgn, 512, 0);
        check(r == -2, "a reset vector of 0x%08X (%s) must be refused at "
              "finalize, not committed (got %d)", bad[i].rv, bad[i].why, r);
        check(commit_word_blank(),
              "a reset vector of 0x%08X (%s) was committed anyway",
              bad[i].rv, bad[i].why);
        check(!dev_finalized(),
              "a reset vector of 0x%08X was reported finalized", bad[i].rv);
        free(img);
    }

    /* The gate must not have become "refuse everything": the boundaries of the
     * accepted window, and the vector the shipping firmware actually carries. */
    for (i = 0; i < sizeof good / sizeof good[0]; i++) {
        uint32_t imgn;
        uint8_t *img = image_with_reset_vector(0x800, 0xE2E2u + i, good[i].rv,
                                               &imgn);
        int r;
        dev_reset();
        r = run_update(img, imgn, 512, 0);
        check(r == 0, "a reset vector of 0x%08X (%s) was refused (%d)",
              good[i].rv, good[i].why, r);
        free(img);
    }

    /* The gates are applied to the bytes that streamed past, not to flash, so
     * they must hold identically on a device with no read-back op — where
     * flash_verify() returns "nothing to verify against" and used to be the
     * only place any application-image test happened at all. */
    {
        uint32_t imgn;
        uint8_t *img = image_with_reset_vector(0x800, 0xE3E3u, 0x00004008u,
                                               &imgn);
        int r;
        dev_reset_noread();
        r = run_update(img, imgn, 512, 0);
        check(r == -2, "with no read-back op, an even reset vector must still "
              "be refused at finalize (got %d)", r);
        check(commit_word_blank(),
              "with no read-back op, an even reset vector was committed");
        free(img);
    }
    {
        uint32_t imgn;
        uint8_t *img = build_image(BL_APP_MIN_LEN - 4u, 0xE4E4u, &imgn);
        int r;
        dev_reset_noread();
        r = run_update(img, imgn, 512, 0);
        check(r == -2, "with no read-back op, an application below "
              "BL_APP_MIN_LEN must still be refused (got %d)", r);
        check(commit_word_blank(),
              "with no read-back op, a too-short application was committed");
        free(img);
    }
}

/* ------------------------------------------------------------------ */
/* Defect 2: range_ok() must reject a wrapping address                 */
/* ------------------------------------------------------------------ */

static void t_range_guard(void)
{
    /* proto.c's range_ok() is the module's single bounds check and the only
     * layer behind the READ path (flash.c's range_writable() covers erase and
     * program, but nothing covers fl_read). It used to test only
     *     len > BL_FLASH_END - addr
     * with no upper bound on addr, so for any addr past the end the unsigned
     * subtraction wrapped to nearly 4 GB and every length passed.
     *
     * Unreachable from the wire today, but a read of unmapped space is the one
     * unrecoverable fault in this design: BusFault -> HardFault -> vector 3
     * trampolines into the application table, which is ERASED mid-update ->
     * spin with CodeFlash unlocked, recoverable only with the H1 jumper. So
     * the guard is asserted directly rather than only through its callers. */
    static const struct { uint32_t addr, len; const char *why; } bad[] = {
        { 0xFFFFFFFFu, 1u,       "the wrap case: one byte at the top of memory" },
        { 0xFFFFFFFCu, 4u,       "a word at the top of memory" },
        { 0xFFFF0000u, 0x200u,   "a whole sector far past the end" },
        { 0x0003E800u, 4u,       "the first byte past CodeFlash" },
        { 0x0003E800u, 0xFFFFFFF0u, "past the end with a wrapping length" },
        { 0x00040000u, 0x200u,   "DataFlash" },
        { 0x20000000u, 4u,       "SRAM" },
        { 0x40001800u, 4u,       "the flash controller's own registers" },
        { 0x00003DFCu, 4u,       "the last word of the bootloader" },
        { 0x00000000u, 4u,       "the reset vector at 0x0000" },
        { 0x0003E7FFu, 2u,       "one byte inside, straddling the end" },
        { 0x00003E00u, 0xFFFFFFFFu, "a length that wraps from a legal address" }
    };
    static const struct { uint32_t addr, len; const char *why; } good[] = {
        { 0x00003E00u, 1u,       "the first writable byte" },
        { 0x00003E00u, 0x3AA00u, "the whole writable window" },
        { 0x0003E7FFu, 1u,       "the last writable byte" },
        { 0x00004000u, 0x200u,   "the first application sector" }
    };
    uint32_t i;

    for (i = 0; i < sizeof bad / sizeof bad[0]; i++)
        check(!bl_proto_range_probe(bad[i].addr, bad[i].len),
              "range_ok(0x%08X, 0x%X) accepted %s", bad[i].addr, bad[i].len,
              bad[i].why);
    for (i = 0; i < sizeof good / sizeof good[0]; i++)
        check(bl_proto_range_probe(good[i].addr, good[i].len),
              "range_ok(0x%08X, 0x%X) refused %s", good[i].addr, good[i].len,
              good[i].why);
    /* ZERO LENGTH — and this is the one assertion in this function that used
     * to be a test of the HOST BUILD ONLY.
     *
     * It read `check(!bl_proto_range_probe(0x3E00, 0), ...)`, i.e. it asserted
     * that range_ok() refuses a zero length. proto.c did carry that test, but
     * the ARM build folded it out: erase_ok passes a constant 0x200, program_ok
     * tests len itself before calling, fl_read tests it too, so no reachable
     * caller can produce len == 0 and the branch was eliminated. The suite was
     * therefore asserting a property the shipped image does not have — the
     * self-comparison problem the harness audit already caught once elsewhere.
     *
     * Resolved in proto.c, not here: range_ok() answers the RANGE question
     * only, so the empty range at a legal address is inside the window (both
     * builds now agree, because there is no longer any special case to fold),
     * and refusing a zero-length OPERATION is each operation's own job at a
     * site where it cannot be folded away. What follows asserts exactly that
     * split. The operation half is covered elsewhere in this file: a 0x24 with
     * chunk_len 0 is NAKed (t_page_size_contract), and bl_proto_selftest()
     * checks
     * program_ok(addr, 0). */
    check(bl_proto_range_probe(0x00003E00u, 0u),
          "range_ok() refused the empty range at the first writable byte");
    check(bl_proto_range_probe(0x0003E7FFu, 0u),
          "range_ok() refused the empty range at the last writable byte");
    check(!bl_proto_range_probe(0x00003DFFu, 0u),
          "range_ok() accepted the empty range below the write floor");
    check(!bl_proto_range_probe(0x0003E800u, 0u),
          "range_ok() accepted the empty range past the window");
}

static void t_record_vs_stream_crc(void)
{
    /* hdr_check() compares the payload CRC STORED in the boot-info record
     * against the CRC of the bytes that actually streamed past. t_header_
     * validation cannot reach that comparison: corrupting offset 6 also breaks
     * the stored header CRC at offset 12, which is checked first and rejects
     * earlier.
     *
     * The case that matters is a boot-info page that is internally consistent
     * — header CRC recomputed over the corrupted 12 bytes — but that describes
     * a different payload from the one being installed. Recompute offset 12 so
     * only the stream-versus-record comparison can refuse it. */
    static const uint16_t flips[] = { 0x0001u, 0x0100u, 0x8000u, 0xFFFFu };
    uint32_t i;

    for (i = 0; i < sizeof flips / sizeof flips[0]; i++) {
        uint32_t imgn;
        uint8_t *img = build_image(0x800, 0xC0FFEEu + i, &imgn);
        uint16_t stored = (uint16_t)(img[6] | (img[7] << 8));
        uint16_t hcrc;
        int r;

        stored ^= flips[i];
        img[6] = (uint8_t)stored; img[7] = (uint8_t)(stored >> 8);
        hcrc = crc16(img, 12);                    /* self-consistent again */
        img[12] = (uint8_t)hcrc; img[13] = (uint8_t)(hcrc >> 8);

        dev_reset();
        r = run_update(img, imgn, 512, 0);
        check(r == -2, "a self-consistent boot-info record whose stored "
              "payload CRC disagrees with the streamed bytes (flip 0x%04X) "
              "should fail at finalize (got %d)", flips[i], r);
        check(commit_word_blank(),
              "flip 0x%04X: the record was committed anyway", flips[i]);
        free(img);
    }
}

static void t_session_edges(void)
{
    uint32_t imgn;
    uint8_t *img = build_image(0x800, 0x1357, &imgn);
    uint16_t plen;
    uint8_t *pl;
    frame_t f;

    /* (a) a data packet arriving AFTER a successful finalize. FlashGBX does
     * not drain its port before closing it, so a late retransmit is possible.
     * It must be NAKed, and must not disturb the committed record. */
    dev_reset();
    check(run_update(img, imgn, 512, 0) == 0, "setup update failed");
    {
        uint8_t before[16], after[16];
        dev_flash_read(0x3E00u, before, 16);
        pl = mk_data_payload(1, img, 512, -1, -1, &plen);
        send_frame(99, BL_CMD_DATA, pl, plen);
        free(pl);
        f = parse_frame(g_rx, g_rxn);
        check(f.valid && f.plen == 3 && f.payload[2] == 0x00,
              "a data packet after a successful finalize must be NAKed");
        dev_flash_read(0x3E00u, after, 16);
        check(memcmp(before, after, 16) == 0,
              "a data packet after finalize modified the boot-info record");
        check(flash_equals(0x3E00u, img, imgn),
              "a data packet after finalize modified the image");
    }

    /* (b) re-finalize with a DIFFERENT image CRC after a success. The
     * idempotent re-ack path is only for the same image; a different CRC is a
     * different image and there is nothing to say yes to. */
    {
        uint16_t c = (uint16_t)(crc16(img, imgn) ^ 0x1234u);
        uint8_t p4[4];
        p4[0] = (uint8_t)(c >> 8); p4[1] = (uint8_t)c;
        p4[2] = (uint8_t)(~c >> 8); p4[3] = (uint8_t)(~c);
        send_frame(100, BL_CMD_FINALIZE, p4, 4);
        f = parse_frame(g_rx, g_rxn);
        check(f.valid && f.plen == 1 && f.payload[0] == 0x00,
              "re-finalize with a different CRC must be refused");
        check(flash_equals(0x3E00u, img, imgn),
              "a refused re-finalize modified the image");
    }
    free(img);

    /* (c) a data packet after a SHORT chunk ended the image. The short chunk
     * is the end-of-image signal; anything after it is a host that lost track,
     * and writing it would extend an image whose length is already fixed in
     * the boot-info record. */
    {
        uint32_t n2;
        uint8_t *img2 = build_image(0x100, 0x2468, &n2);   /* 0x300: 512 + 256 */
        uint16_t p2;
        uint8_t *q;
        dev_reset();
        send_frame(1, BL_CMD_INIT, 0, 0);
        q = mk_data_payload(1, img2, 512, -1, -1, &p2);
        send_frame(2, BL_CMD_DATA, q, p2);
        free(q);
        q = mk_data_payload(2, img2 + 512, 256, -1, -1, &p2);
        send_frame(3, BL_CMD_DATA, q, p2);
        free(q);
        f = parse_frame(g_rx, g_rxn);
        check(f.valid && f.payload[2] == 0x01, "the short final chunk failed");
        check(dev_proto_stat(DEV_PS_SHORT_SEEN) == 1,
              "a short chunk should have ended the image");

        q = mk_data_payload(3, img2, 512, -1, -1, &p2);
        send_frame(4, BL_CMD_DATA, q, p2);
        free(q);
        f = parse_frame(g_rx, g_rxn);
        check(f.valid && f.plen == 3 && f.payload[2] == 0x00,
              "a data packet after the image ended must be NAKed");
        check(dev_proto_stat(DEV_PS_NEXT_INDEX) == 3,
              "a NAKed packet must not advance the index");
        free(img2);
    }
}

static void t_feed_buf(void)
{
    /* bl_proto_feed_buf() is the only entry point in proto.c with no caller
     * anywhere in src/, and it is the presumed stage-3 USB integration point.
     * Drive a whole update through it, including its tx callback, rather than
     * letting it first meet a real host on real hardware. */
    uint32_t imgn;
    uint8_t *img = build_image(0xA00, 0xFEED, &imgn);
    int r;

    dev_reset();
    g_use_feed_buf = 1;
    r = run_update(img, imgn, 512, 0);
    g_use_feed_buf = 0;
    check(r == 0, "an update driven through bl_proto_feed_buf returned %d", r);
    check(flash_equals(0x3E00u, img, imgn),
          "bl_proto_feed_buf produced a different image");
    check(dev_finalized(), "bl_proto_feed_buf did not finalize");
    check(dev_bootloader_intact(), "bl_proto_feed_buf modified the bootloader");
    free(img);
}

static void t_reset_preserves_ops(void)
{
    /* proto.h documents that a driver bound with bl_proto_bind() survives
     * bl_proto_reset() — the BL_PROTO_MAGIC branch — because a USB reset may
     * legitimately reset the protocol object mid-session and must not silently
     * unbind the flash driver. Every other entry point in this harness
     * memsets the object first, so that branch had never been taken. */
    uint32_t imgn;
    uint8_t *img = build_image(0x600, 0xBEE5, &imgn);
    uint16_t plen;
    uint8_t *pl;
    int r;

    dev_reset();
    send_frame(1, BL_CMD_INIT, 0, 0);
    pl = mk_data_payload(1, img, 512, -1, -1, &plen);
    send_frame(2, BL_CMD_DATA, pl, plen);
    free(pl);
    check(dev_proto_stat(DEV_PS_NEXT_INDEX) == 2, "setup packet was not taken");

    dev_reset_preserve();
    check(dev_proto_stat(DEV_PS_NEXT_INDEX) == 1,
          "bl_proto_reset() did not restart the session");
    check(dev_proto_stat(DEV_PS_STATE) == 0,
          "bl_proto_reset() did not return the framer to the intro hunt");
    check(dev_proto_stat(DEV_PS_HAVE_HDR) == 0 &&
          dev_proto_stat(DEV_PS_BYTES) == 0,
          "bl_proto_reset() left session state behind");

    /* If the ops vector had been dropped, every data packet would now be
     * NAKed and this update would return -1. */
    r = run_update(img, imgn, 512, 0);
    check(r == 0, "the flash driver did not survive bl_proto_reset() (%d)", r);
    check(flash_equals(0x3E00u, img, imgn),
          "image mismatch after a driver-preserving reset");
    free(img);
}

/* A stock vendor fw.bin, if one is reachable.
 *
 * It is NOT redistributed with this project, so every use of it here is
 * optional: with it, the replays additionally prove the modelled flash ends up
 * byte-identical to the real image; without it, the recorded response streams
 * are still replayed and compared byte for byte, which is the core claim.
 * Point GBFLASH_FW at a stock image to enable the extra checks. */
static const char *fw_image_path(void)
{
    static char resolved[1024];
    static int  tried;
    static const char *dirs[3];
    uint32_t dummy;
    int d;

    if (tried)
        return resolved[0] ? resolved : 0;
    tried = 1;
    /* The image the fixtures were generated from. gen_streams.py writes it next
     * to them, so the fixture set is self-describing and this test needs no file
     * from outside the repository. By default that image is synthetic — the
     * protocol layer never inspects payload meaning, only framing, CRCs,
     * sequencing and lengths, so a structurally valid image exercises exactly
     * the same paths. Set GBFLASH_FW (and regenerate) to rehearse against a real
     * fw.bin locally. */
    dirs[0] = getenv("GBFLASH_FW");
    dirs[1] = "fixtures/image.bin";
    dirs[2] = "../fixtures/image.bin";
    for (d = 0; d < 3; d++) {
        uint8_t *p;
        if (!dirs[d]) continue;
        p = slurp(dirs[d], &dummy);
        if (p) {
            free(p);
            snprintf(resolved, sizeof resolved, "%s", dirs[d]);
            return resolved;
        }
    }
    return 0;
}

static void t_selftest(void)
{
    uint32_t n = 0;
    uint8_t *fw = 0;
    const char *path = fw_image_path();
    int r = bl_proto_selftest();
    check(r == 0, "bl_proto_selftest() failed at check %d", r);

    /* Known-answer vectors for the CRC16 itself, independent of any firmware
     * image. These pin the nibble-table MODBUS-style algorithm (init 0xFFFF)
     * that both the boot-info record and the 0x23 finalize depend on; getting it
     * wrong silently would make every update fail its final check.
     *
     * This used to assert CRC16 over a stock vendor fw.bin instead, which tied a
     * pure algorithm test to a file the repository does not ship. */
    {
        static const uint8_t empty[1] = { 0 };
        static const uint8_t abc[3]   = { 'a', 'b', 'c' };
        static const uint8_t zeros[8] = { 0, 0, 0, 0, 0, 0, 0, 0 };
        static const uint8_t ffs[8]   = { 0xFF, 0xFF, 0xFF, 0xFF,
                                          0xFF, 0xFF, 0xFF, 0xFF };
        /* The conventional CRC check string, so this algorithm can be compared
         * against published values for CRC-16/MODBUS by anyone auditing it. */
        static const uint8_t check9[9] = { '1', '2', '3', '4', '5',
                                           '6', '7', '8', '9' };
        uint16_t c;

        c = crc16(empty, 0);
        check(c == 0xFFFFu, "CRC16(<empty>) = 0x%04X, expected 0xFFFF", c);
        c = crc16(abc, sizeof abc);
        check(c == 0x5749u, "CRC16(\"abc\") = 0x%04X, expected 0x5749", c);
        c = crc16(zeros, sizeof zeros);
        check(c == 0x0B40u, "CRC16(8x00) = 0x%04X, expected 0x0B40", c);
        c = crc16(ffs, sizeof ffs);
        check(c == 0x8F01u, "CRC16(8xFF) = 0x%04X, expected 0x8F01", c);
        c = crc16(check9, sizeof check9);
        check(c == 0x4B37u, "CRC16(\"123456789\") = 0x%04X, expected 0x4B37", c);
    }

    /* The reference image the fixtures were built from must be internally
     * consistent: both stored CRCs recompute, so the structural gates the
     * writer and the validator apply are exercised against a real record. */
    if (path) fw = slurp(path, &n);
    if (fw) {
        r = bl_proto_selftest_image(fw, n);
        check(r == 0, "bl_proto_selftest_image() failed at check %d", r);
        free(fw);
    } else {
        printf("  image self-test: skipped, fixtures/image.bin missing "
               "(run `make fixtures`)\n");
    }
}

/* ------------------------------------------------------------------ */

int main(int argc, char **argv)
{
    if (argc > 1) g_fixdir = argv[1];
    /* Unbuffered: if a check ever wedges the parser in an infinite loop, the
     * last line printed is the one that did it. */
    setvbuf(stdout, 0, _IONBF, 0);
    g_rx = malloc(RXCAP);

    group("proto.c self-test and known-answer CRCs");
    t_selftest();
    t_range_guard();

    group("replay of real updater byte streams");
    if (!fw_image_path())
        printf("  note: no stock fw.bin reachable, so the replays check the\n"
               "        recorded response streams but not the reconstructed\n"
               "        image. Set GBFLASH_FW to enable the image checks.\n");
    replay("flashgbx",     fw_image_path());
    replay("flashgbx_gui", fw_image_path());
    replay("unlocker",     fw_image_path());
    {
        /* getserial flashes its own se.pkbin, which is third-party and is NOT
         * redistributed here — so in a plain checkout neither host/vendor/ nor
         * the fixture exists and this replay skips itself with a note.  Set
         * GETSERIAL_DIR to a directory holding se.pkbin to run it locally. */
        static const char *dirs[2];
        uint32_t dummy, d;
        char path[1024];
        dirs[0] = getenv("GETSERIAL_DIR");
        dirs[1] = "vendor/getserial";
        path[0] = 0;
        for (d = 0; d < 2; d++) {
            uint8_t *p;
            if (!dirs[d]) continue;
            snprintf(path, sizeof path, "%s/se.pkbin", dirs[d]);
            p = slurp(path, &dummy);
            if (p) { free(p); break; }
            path[0] = 0;
        }
        if (path[0]) replay("getserial", path);
        else printf("  getserial: skipped, se.pkbin not found\n");
    }

    group("stray trigger bytes and resynchronisation");
    t_stray_trigger_bytes();
    t_truncated_then_valid();
    t_resync_worst_case();
    t_implausible_headers();
    t_truncated_data_frame();
    t_idle_is_safe();
    t_intro_inside_payload();
    {
        uint32_t i, worst = 1;
        for (i = 0; i < 64; i++) if (g_resync_cost[i] > worst) worst = g_resync_cost[i];
        printf("  truncated-frame resync: worst case %u init frames "
               "(both hosts send 2)\n", worst);
    }

    group("init handshake");
    t_init_once_and_twice();
    t_init_midsession();
    t_finalized_cleared_by_init();

    group("framing limits");
    t_oversize_payload();
    t_odd_and_even_payloads();

    group("data packets");
    t_bad_chunk_crc_then_retry();
    t_index_order();
    t_page_size_contract();
    t_data_without_init();

    group("finalize and the boot-info commit");
    t_finalize_paths();
    t_header_validation();
    t_record_vs_stream_crc();
    t_app_sp_gate();
    t_app_reset_vector_gate();
    t_interrupted_update();
    t_session_edges();

    group("image shapes");
    t_image_shapes();

    group("degraded flash drivers");
    t_no_flash_driver();
    t_no_readback_op();

    group("flash that misbehaves");
    t_flash_failures();

    group("entry points and object lifetime");
    t_feed_buf();
    t_reset_preserves_ops();

    free(g_rx);
    /* Both numbers, deliberately. The execution count alone reads as breadth
     * it does not have: it is dominated by loops, most of all the replay
     * loop's five assertions per response frame. */
    printf("\n%d assertions, %d executions passed, %d failed, %d notes\n",
           g_nsites, g_pass, g_fail, g_warn);
    return g_fail ? 1 : 0;
}
